WITH payload AS (SELECT $archive_payload$[{"id":"ca682494-cbb2-57ed-ad96-9ae2107cfeb6","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع اسطوانات مدمجة محمل عليها مقاطع إباحية -ترويج اسطوانات مدمجة محمل عليها مقاطع خليعة ( إباحية ) -إنكار املدعى عليه -البينة التي لم تشهد صراحة بكافة أركان الوصف اإلجرامي ال يثبت بها الوصف إال أنها قد تورثه التهمة (الشبهة) املوجبة للتعزير -التعزير بالسجن واجللد.","document_number":"3438115","case_number":"3428575","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/16","year":"1434","subject":"بيع اسطوانات مدمجة محمل عليها مقاطع إباحية -ترويج اسطوانات مدمجة محمل عليها مقاطع خليعة ( إباحية ) -إنكار املدعى عليه -البينة التي لم تشهد صراحة بكافة أركان الوصف اإلجرامي ال يثبت بها الوصف إال أنها قد تورثه التهمة (الشبهة) املوجبة للتعزير -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3438115 :‬تاريخه‪1434/2/16 :‬هـ‬\n                         ‫رقم الدعوى‪3428575:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34169436‬تاريخه‪1434/4/13 :‬هـ‬\n\n\n     ‫بيــع اســطوانات مدمجــة محمــل عليهــا مقاطــع إباحيــة ‪ -‬ترويــج‬\n     ‫اســطوانات مدمجــة محمــل عليهــا مقاطــع خليعــة ( إباحيــة ) ‪ -‬إنــكار‬\n     ‫املدعــى عليــه ‪ -‬البينــة التــي لــم تشــهد صراحــة بكافــة أركان الوصــف‬\n     ‫اإلجرامــي ال يثبــت بهــا الوصــف إال أنهــا قــد تورثــه التهمــة (الشــبهة)‬\n                                ‫املوجبــة للتعزيــر ‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n                                       ‫‪ -‬ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بقيامــه بترويــج‬\n     ‫أقــراص حتتــوي علــى مقاطــع جنســية خليعــة وطلــب إثبــات مــا أســند إليــه‬\n     ‫واحلكــم عليــه بعقوبــة تعزيريــة ‪ ،‬أنكــر املدعــى عليــه الدعــوى ودفــع‬\n     ‫بــأن األقــراص املضبوطــة ال تعــود لــه وإمنــا بجــواره وأن صاحبهــا هــرب‬\n     ‫ملــا شــاهد أعضــاء الهيئــة وأن بينــه وبــن البســطة املجــاورة لبســطته‬\n     ‫قرابــة متــر أو متــر ونصــف ‪ ،‬جــرى االطــاع علــى محضــر القبــض‬\n     ‫وعرضــه علــى املتهــم فأنكــره فطلبــت احملكمــة مــن املدعــي العــام‬\n     ‫إحضــار معديــه لســماع مــا لديهــم مــن شــهادة ‪ ،‬حضــر عضــوي هيئــة‬\n     ‫األمــر باملعــروف وشــهد كل واحــد منهمــا منفــردا بأنــه ورد بــاغ عــن‬\n\n‫‪87‬‬\n\f‫قيــام شــخص يف موقــع القبــض علــى املدعــى عليــه يقــوم ببيــع أقــراص‬\n‫حتتــوي علــى مقاطــع خليعــة فتوجهــا للموقــع فلمــا رآهــم املدعــى عليــه‬\n‫حــاول الهــرب فتــم القبــض عليــه فقــال لهمــا حينــه بــأن البســطة لشــخص‬\n‫آخــر مــن جنســيته فطلبــا منــه أن يتصــل عليــه أو يدلهمــا علــى منزلــه‬\n‫فلــم يفعــل ولــم يشــاهدا غيــره يف احملــل وقــد اتضــح مــن األقــراص بأنهــا‬\n‫مخلــة كمــا يف احملضــر املعــد وبعــرض شــهادتهما علــى املدعــى عليــه‬\n‫أصــر علــى إنــكاره وبنــاء علــى إنــكار املدعــى عليــه ‪ ،‬وألن البينــة غيــر‬\n‫موصلــة حيــث لــم تشــهد بعمــل الترويــج إال أن مــا ورد فيهــا تلحــق التهمــة‬\n‫القويــة املوجبــة للتعزيــر لــذا قــررت احملكمــة عــدم إدانــة املدعــى عليــه‬\n‫مبــا نســب إليــه مــن ترويــج وتوجيــه التهمــة القويــة عليــه بذلــك وتعزيــره‬\n‫ألجلــه بســجنه خمســة أشــهر مــن تاريــخ إيقافــه وجلــده مئــة وخمســن‬\n‫جلــدة مجزئــة علــى ثــاث دفعــات متســاوية بــن كل دفعــة واألخــرى‬\n‫خمســة عشــر يومــا ‪ ،‬قــرر املدعــى عليــه القناعــة باحلكــم بينمــا قــرر‬\n‫املدعــي العــام االعتــراض بتقــدمي الئحــة اعتراضيــة فأفهــم بتعليمــات‬\n                 ‫االعتــراض ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 3428575‬وتاريــخ ‪ 1434/01/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34138151‬وتاريــخ ‪ 1434/01/17‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/02/09‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ...........‬وادعــى قائــا بصفتــي عضــو هيئــة‬\n\n                                                                                     ‫‪88‬‬\n\f     ‫التحقيــق واالدعــاء العــام مبدينــة الريــاض ادعــي علــى ‪ 36 .......... /‬ســنة‬\n     ‫‪ ،‬مينــي اجلنســية مبوجــب إثبــات هويــة مؤقتــة محصــن موقــوف مبوجــب‬\n     ‫أمــر اإلحالــة ومتديــد التوقيــف رقــم ه ـ ‪...........‬وتاريــخ‪1434 / 1 /8‬ه ـ‬\n     ‫اســتنادا للمادتــن (‪)121-108‬مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬حيــث‬\n     ‫إنــه بتاريخ‪1434/1/4‬ه ـ قبــض علــى املذكــور مــن قبــل هيئــة األمــر‬\n     ‫باملعــروف والنهــي عــن املنكــر ‪ ،‬مركــز هيئــة األمــر باملعــروف والنهــي‬\n     ‫عــن املنكــر أثــر بــاغ عــن قيــام شــخص مينــي اجلنســية باملجاهــرة بترويــج‬\n     ‫وبيع الســيدات اجلنســية اخلليعة وبســط تلك البضاعة أمام مطعم وبيعها‬\n     ‫علــى املــارة ومرتــادي املطعــم وباالنتقــال للموقــع شــوهد املذكــور وقــد‬\n     ‫عــرض بضاعتــه أمــام املطعــم مــن مالبــس وســيدات وبشــاهدته للفرقــة‬\n     ‫بــدأت عليــة عالمــات االرتبــاك واخلــوف وحــاول مغــادرة املــكان فتــم‬\n     ‫اســتيقافه وضبــط بحوزتــه ثالثمائــة وثمانيــة عشــر ســيدي وبالكشــف‬\n     ‫عليهــا تبــن وجــود ثالثــة ســيديات حتــوي علــى مشــاهد مثيــرة للجنــس‬\n     ‫متــارس فيهــا فاحشــة الزنــا وثالثــة ســيديات متــارس فيهــا مقدمــات‬\n     ‫الفاحشــة وأربعــة ســيديات حتتــوي علــى مشــاهد لنســاء شــبة عاريــات‬\n                                 ‫وقــد ذكــر بأنــه يبيــع الســيدي بعشــرة ريــاالت‪.‬‬\n     ‫واســفرت إجــراءات التحقيــق عــن إتهــام ‪........‬بترويــج ســيديات خليعــة‬\n                                                 ‫وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n                  ‫‪ - 1‬ما ورد يف أقواله املدونة مبلف التحقيق املرفق لفة ( ) ‪.‬‬\n                                  ‫‪ - 2‬ما جاء يف محضر القبض املرفق لفة ‪) (.‬‬\n                                      ‫‪ - 3‬محضر املشاهدة املرفق لفة رقم ( )‪.‬‬\n     ‫وببحــث ســوابقه اتضــح عــدم و جــود ســوابق مســجله عليــه حتــى تاريخــه‬\n                                                                                      ‫‪.‬‬\n\n\n‫‪89‬‬\n\f‫وحيــث إن مــا اقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا‬\n‫أســند إليــه وبــاهلل التوفيــق ‪ ، ، ،‬وبســؤال املدعــى عليــه أجــاب بقولــه مــا‬\n‫ذكــره املدعــي العــام غيــر صحيــح والصحيــح انــه يوجــد شــخص قريــب‬\n‫بســطتي يبيــع ســيديات فلمــا حضــرت الهيئــة هــرب ومت القبــض علــي‬\n‫واال شــرطة ال تعــود لــي وال اعلــم عنهــا شــيء علمــا انــه يوجــد مســاحه بني‬\n‫املــكان الــذي ابيــع فيــه وبــن مــكان الشــخص الــذي يبيــع الســيديات‬\n‫قدرهــا متــر أو متــر ونصــف وبعــرض ذلــك املدعــي العــام وســؤاله البينــة‬\n‫قــال الصحيــح مــا ذكــرت وبينتــي مــا يف اوراق املعاملــة وبتصفحهــا‬\n‫وجــد علــى اللفــة ‪ 4‬محضــر قبــض معــد مــن مركــز هيئــة ‪ ...........‬برقــم‬\n‫‪ 21/29‬يف ‪1434/1/4‬ه ـ متضمــن ملــا اشــير إليــه يف الئحــة االدعــاء‬\n‫وبعــرض عليــه قــال الصحيــح مــا ذكــرت عليــه وافهمــت املدعــي العــام‬\n‫بإحضــار معــدي احملضــر ال داء مــا لديهــم مــن شــهاده ورفعــت اجللســة‬\n‫لذلــك يــوم الســبت ‪1434/2/16‬ه ـ وصلــى اهلل وســلم علــي نبينــا محمــد‬\n‫حــرر يف ‪1434/2/9‬ه ـ ويف يــوم الســبت املوافق ‪1434/2/16‬هـ الســاعة‬\n‫العاشــرة افتتحــت اجللســة وفيهــا حضــر ‪...........‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ...........‬وقــال انــي مولــود عــام ‪1391‬ه ـ اعمــل مبركــز هيئــة‬\n‫‪...........‬و‪...........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...........‬وقــال انــي‬\n‫مولــود عــام ‪1409‬ه ـ واعمــل مبركــز هيئــة ‪...........‬وقــال كل واحــد‬\n‫منهمــا علــى انفــراد اشــهد انــه وردنــا بالغــات عــن شــخص ميانــي اجلنســية‬\n‫يبيــع ســيديات إباحيــة مخلــه يف حــي ‪...........‬أمــام أحــد املطاعــم فتوجهنــا‬\n‫للمــكان وشــاهدنا املدعــى عليــه امــام بســطة بهــا مالبــس واشــرطة‬\n‫ســيديات وملــا شــاهدنا حــاول الهــرب فتــم القبــض عليــه وقــال انهــا‬\n\n\n                                                                                        ‫‪90‬‬\n\f     ‫ليســت لــي وامنــا لشــخص ميانــي اخــر فطلبنــا منــه ان يتصــل عليــه او يقــوم‬\n     ‫بالداللــة علــى منزلــه فلــم يتصــل علــى احــد ولــم نشــاهد احــد غيــره وقــد‬\n     ‫اتضــح ان االشــرطة مخلــه كمــا يف احملضــر هــذا مــا لــدي مــن شــهادة‬\n     ‫علمــا ان مــا مت فحصــه عبــاره عــن عينــة فقــط وبعــرض الشــهادة علــى‬\n     ‫املدعــى عليــه قــال الصحيــح مــا ذكــره فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واالجابــة وحيــث ان بينــة املدعــي العــام غيــر موصلــه إلدانــة املدعــى عليــه‬\n     ‫بالترويــج ولكــن مــا ورد يف شــهادة الشــاهدين قرينــة تقــوي التهمــه‬\n     ‫بإدانتــه مبــا نســب اليــه مــن ترويــج لــذا قــررت مــا يلــي اوال عــدم ادانــة‬\n     ‫املدعــى عليــه مبــا نســب اليــه مــن الترويــج وتوجــه التهمــه القويــة عليــه‬\n     ‫بذلــك ثانيــا تعزيــره للتهمــة القويــة بالســجن خمســة اشــهر ابتــداء مــن‬\n     ‫تاريــخ ايقافــه وجلــده مائــة وعشــرين جلــده مجزئــة علــى ثــاث دفعــات‬\n     ‫متســاوية بــن كل دفعــه واخــرى خمســة عشــر يومــا وبعــرض احلكــم‬\n     ‫علــى الطرفــن قــررا املدعــى عليــه قناعتــه باحلكــم وقــرر املدعــي العــام‬\n     ‫عــدم قناعتــه ورغــب يف تقــدمي الئحــة فجــرى تســليمه نســخه مــن احلكــم‬\n     ‫وافهــم بــان مــدة االعتــراض ثالثــون يــوم اعتبــار مــن اليــوم واذا لــم يقــدم‬\n     ‫اعتراضــه خاللهــا يســقط حقــه يف االعتــراض وترفــع االوراق حملكمــة‬\n     ‫االســتئناف بــدون الئحــة وصلــى اهلل وســلم علــى نبينــا محمــد ويف‬\n     ‫يــوم االحــد املوافــق ‪1434/2/24‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n     ‫وقــال املدعــي العــام انــي اكتفــي مبــا يف الالئحــة واعتبرهــا الئحتــي‬\n     ‫االعتراضيــة وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪24/2/1434‬‬\n     ‫ه ـ احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n     ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n\n\n‫‪91‬‬\n\f‫‪ 34138151‬وتاريــخ ‪1434/3/1‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪........... /‬املســجل برقــم ‪3438115‬‬\n‫وتاريــخ ‪1434/2/16‬ه ـ اخلــاص بدعــوى املدعــى العــام ضــد ‪........... /‬‬\n‫مينــي اجلنســية ) يف قضيــة ترويــج مقاطــع إباحيــة علــى النحــو املوضــح‬\n‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون و مفصــل بــه و بدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر لألكثريــة مــا يوجــب‬\n‫املالحظــة علــى احلكــم مــع التنبــه إلــى تصحيــح األخطــاء االمالئيــة يف‬\n‫الصفحــة األولــى مــن القــرار املعلــم عليهــا بقلــم الرصــاص وتوقيــع القــرار‬\n‫واملصادقــة عليهــا مــن قبــل رئيــس احملكمــة قبــل ارســال املعاملــة جلهــة‬\n‫التنفيــذ ومالحظــة ذلــك مســتقبالً‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":87,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"727a678b1f108be8bed8a11bc5837260c66bf1f2146731494efcbef12b7a8f0a","normalized_text_hash":"4f1f5f38bbfcfa32b4cc06f49a93981e76ca75550ed64b4f2be7352e611773a2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p87-3438115"},{"id":"b3182991-591d-5272-8bb7-f82e5710569a","document_type":"judgment","category":"judicial","subcategory":"general","title":"ابتزاز -ابتزاز فتاة جنسي ا -تهديد بنشر صور -خلوة محرمة - إقامة عالقة محرمة مع فتاة -جرائم معلوماتية -تعزير بالسجن واجللد ومصادرة األجهزة املستعملة والغرامة.","document_number":"3451637","case_number":"3478036","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/1","year":"1434","subject":"ابتزاز -ابتزاز فتاة جنسي ا -تهديد بنشر صور -خلوة محرمة - إقامة عالقة محرمة مع فتاة -جرائم معلوماتية -تعزير بالسجن واجللد ومصادرة األجهزة املستعملة والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3451637 :‬تاريخه‪1434/3/1 :‬هـ‬\n                         ‫رقم الدعوى‪3478036:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3463319‬تاريخه‪1434/3/16 :‬هـ‬\n\n\n     ‫ابتــزاز ‪ -‬ابتــزاز فتــاة جنســي ًا ‪ -‬تهديــد بنشــر صــور ‪ -‬خلــوة محرمــة ‪-‬‬\n     ‫إقامــة عالقــة محرمــة مــع فتــاة ‪ -‬جرائــم معلوماتيــة ‪ -‬تعزيــر بالســجن‬\n                            ‫واجللــد ومصــادرة األجهــزة املســتعملة والغرامــة‪.‬‬\n\n\n\n\n     ‫‪ -1‬قــول اهلل تعالــى ‪ «:‬إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن‬\n                               ‫آمنــوا لهــم عــذاب أليــم يف الدنيــا واآلخــرة »‪.‬‬\n                            ‫‪ -2‬املادة الثالثة من نظام اجلرائم املعلوماتية ‪.‬‬\n                           ‫‪ -3‬املادة السادسة من نظام اجلرائم املعلوماتية‬\n                      ‫‪ -4‬املادة الثالثة عشرة من نظام اجلرائم املعلوماتية‪.‬‬\n                                        ‫‪ -5‬ما أشير له يف احلكم من تسبيب‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن املدعــي العــام علــى املدعــى عليــه بإقامــة‬\n     ‫عالقــة محرمــة مــع فتــاة ال متــت لــه بصلــة شــرعية وتهديدهــا وابتزازهــا‬\n     ‫بنشــر صورهــا وتخزيــن وإرســال مــا مــن شــأنه املســاس بــاآلداب العامــة‬\n     ‫وحرمــة احليــاة اخلاصــة بهاتفهــا اجلــوال مطالبــا باحلكــم عليــه بالســجن‬\n     ‫والغرامــة أو بأحدهمــا وفقــا لنظــام اجلرائــم املعلوماتيــة ومصــادرة أجهــزة‬\n     ‫اجلــوال املســتعملة يف اجلرميــة وإيقــاع عقوبــة تعزيريــة لقــاء إقامتــه عالقــة‬\n\n‫‪93‬‬\n\f‫محرمــة حيــث ورد بــاغ لهيئــة األمــر باملعــروف والنهــي عــن املنكــر مــن‬\n‫فتــاة بأنهــا كانــت علــى عالقــة معــه عبــر الهاتــف ثــم طلبــت منــه قطــع‬\n‫العالقــة إال أنــه أخــذ يبتزهــا ويهددهــا بنشــر صورهــا فجــرى التنســيق‬\n‫معهــا مبجاراتــه وتواعــدت معــه علــى مــكان فجــرى القبــض عليــه ‪،‬‬\n‫أقــر املدعــى عليــه بإقامــة عالقــة محرمــة وبعــث رســائل تهديــد ‪ ،‬تنازلــت‬\n‫املجنــي عليهــا عــن دعواهــا ضــد املدعــى عليــه ‪ ،‬بنــاء علــى إقــرار املدعــى‬\n‫عليــه بجرمــه فقــد حكمــت احملكمــة بإدانتــه مبــا نســب إليــه وســجنه‬\n‫ســنة مــن تاريــخ إيقافــه وغرامــة ماليــة عشــرة آالف ريــال وجلــده خمســن‬\n‫جلــدة مفرقــة علــى دفعــات أحدهــا أمــام جامعــة البنــات ومصــادرة أجهــزة‬\n‫اجلــوال وجعــل عقوبــة إقامتــه عالقــة محرمــة داخلــة ضمــن هــذه العقوبــة‬\n‫‪ ،‬قــرر املدعــى عليــه القناعــة ‪ ،‬قــرر املدعــي العــام عــدم القناعــة بالئحــة‬\n                                 ‫‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق ‪1434/3/1‬هـ ـ‬\n‫الســاعة التاســعة صباحــا لــدي أنــا ‪..........‬القائــم بعمــل فضيلــة الشــيخ‬\n‫وبناء علــى املعاملة املقيدة‬\n                        ‫ً‬    ‫‪..........‬القاضــي باحملكمــة اجلزائيــة بالطائــف‬\n‫برقم‪34392910‬يف‪1434/2/17‬هـ واحملالة إلينا بشرح فضيلة الرئيس‬\n‫رقم‪3478036‬يف‪1434/2/17‬هـ ـ افتتحــت اجللســة وفيهــا حضــر املدعــى‬\n‫العــام‪ ........../‬بالتعميــد رقــم ‪..........‬يف ‪1433/10/18‬هـ ـ وادعــى علــى‬\n‫احلاضــر باملجلــس الشــرعي‪.......... /‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪..........‬قائــا إنــه بتاريــخ ‪1433/8/5‬ه ـ ورد ملركــز شــرطة‬\n‫‪..........‬محضــر هيئــة االمــر باملعــروف املتضمــن بــاغ ملركــز هيئــة األمــر‬\n\n                                                                                      ‫‪94‬‬\n\f     ‫باملعــروف و النهــي عــن املنكــر مــن فتــاة تذكــر فيــه تعرضهــا لالبتــزاز‬\n     ‫مــن قبــل املدعــى عليــه حيــث كانــت علــى عالقــة هاتفيــة معــه وطلبــت‬\n     ‫منــه الكــف عــن االتصــال بهــا وقطــع العالقــة بينهمــا اال أن الشــاب قــام‬\n     ‫بتهديدهــا بنشــر صورهــا ورســائلها ومالحقتهــا وذكــرت يف بالغهــا أنــه‬\n     ‫قــام بكتابــة ورقــة صغيــره يهددهــا فيهــا ووضعها يف ســيارة احد اخوتها‬\n     ‫والــذي قــام بــدوره مبناصحتــه إال أنــه لــم يســتجب ألخيهــا بل قام بإرســال‬\n     ‫صورهــا علــى جــوال أخيهــا وهــي اآلن يف حالــة نفســية ســيئة وتطلــب‬\n     ‫كــف أذى الشــاب عنهــا و انــه اتصــل بهــا طالب ـ ًا منهــا اخلــروج معــه مــن‬\n     ‫جامعتهــا وإال ســوف تنــدم طــوال حياتهــا فتــم التنســيق معهــا مبجاراتــه‬\n     ‫حيــث اخبرهــا مبواصفــات ســيارته و مــكان تواجــده و بالقبــض عليــه‬\n     ‫ظهــرت عليــه عالمــات اخلــوف وطلــب الســتر عليــه وأفــاد بعالقتــه بالفتــاة‬\n     ‫وحيازتــه لصورهــا بجوالــه مــن نــوع ‪ .....‬وبتفتيشــه عثــر بحوزتــه علــى‬\n     ‫‪ 3‬اجهــزة جــوال األول مــن ‪ .....‬يحمــل الرقــم (‪ )..........‬والثانــي مــن ‪......‬‬\n     ‫برقم(‪)..........‬والثالــث مــن نــوع ‪ .....‬يحمــل الرقــم (‪ )..........‬وبتفريــغ‬\n     ‫الرســائل مــن جــوال الفتــاة املشــتكية و املرســلة مــن جــوال املدعــى‬\n     ‫عليــه وهــي كالتالــي ‪/1 :‬رســالة نصيــة (اهلل ال يوفقنــي إنــي أرســلت‬\n     ‫صــورك علــى أخــوك وقلــت لــه تبــي تســوية وراح اطبــع صــورك مــرة‬\n     ‫ثانيــة يــا بنــت الكلــب )‪/2‬رســالة نصيــة (تعطينــي رقــم مــا هــو رقمــك‬\n     ‫تبغينــي أســكت ) ‪/‬رســالة نصيــة (يف ذهنــي ال فضحــك )‪/4‬أنــا واقــف‬\n     ‫مقابــل البوابــة ســيارة بيضــاء ســيارة ابــوك بنيــة صح)‪/5‬رســالة نصيــة‬\n     ‫(فضيحــة قــادم أبــوك وزميالتــك متــى تطلعــن )‪/6‬رســالة نصيــة (ترانــي‬\n     ‫عنــد اجلامعــة ردي أبخرجها)‪/7‬رســالة نصيــة (شــفتي إنــك كذابــة ونــا‬\n     ‫بــري تبغينــي أحــرق الصــور ردي)‪/8‬رســالة نصيــة(دام عرفــت بيتكــم‬\n\n\n‫‪95‬‬\n\f‫وأســاميكم الليلــة تعطينــي الرقــم غصبـ ًا عنــك )‪(/9‬كلمينــي ابشــوف‬\n‫لتســمعني كالمــي أنــا قلــت إذا مــا ســمعتيني كل اســبوع أبســوي شــيء‬\n‫)‪(/10‬أنــا انــذرك وعطيــك فرصــة بعدهــا أسوي)‪/11‬رســالة نصيــة‬\n‫(ياليــت مــا ترديــن ابيــك تشــوفني وش اســوي فيكــم) ‪/12‬رســالة نصيــة‬\n‫(اذا مــا خليــت كل جماعتكــم يعرفــون ويشــوفون صــورك وفضحــة‬\n‫اهلــك معــك ) ‪/13‬رســالة نصيــة (أنــا حلفــت لــو متــر الليلــة مــا ترديــن‬\n‫‪..........‬و‪ ..........‬و ‪..........‬يشــوفون صــورك وجســمك )‪/14‬رســالة نصيــة‬\n‫(أقســم بــاهلل اللــي ســويته شــيء بســيط اجلــاي اكبــر ومــا احــد بيخســر‬\n‫إال أهلــك )‪/15‬رســالة نصية(مــا شــفتي شــي )صــدر امــر حجــز االجهــزة‬\n‫اجلــواالت املضبوطــة مــع املدعــى عليــه مبوجــب امــر احلجــز (‪ )..........‬يف‬\n‫‪1434/2/9‬ه ـ و باســتجواب املدعــى عليــه أقــر بوجــود عالقــة لــه مــع‬\n‫الفتــاة منــذ ســنتني و أقــر بوجــود عــدد ‪ 3‬صــور لتلــك الفتــاة أحداهــا‬\n‫يظهــر وجههــا واآلخــرى يظهــر جســمها وانــه قــام بتهديدهــا بنشــر‬\n‫صورهــا إذا لــم تــرد علــى اتصاالتــه وأقــر أنــه قــام بإرســال صورتهــا علــى‬\n‫شــقيقها كمــا أقــر بوجــود صــور لفتيــات اخريــات بجهــاز جوالــه مــن‬\n‫نــوع ‪ ....‬باالطــاع أجهــزة اجلــوال االول املضبوطــة مــع املدعــي عليــه مــن‬\n‫نــوع ‪ .....‬وهــو اجلهــاز الــذي أقــر املدعــى عليــه بانــه قــام بإرســال رســائل‬\n‫التهديــد منــه وجــد مقفــل برقــم ســري غيــر معــروف جلهــة الضبــط و‬\n‫الثانــي جــوال مــن نــوع ‪ .....‬اللــون رصاصــي بــه مقطــع فيديــو يظهــر فيــه‬\n‫فتــاة شــبه عاريــة وصورتــن لتلــك الفتــاة يظهــر فيهــا وجههــا ثالثـ ًا جــوال‬\n‫مــن نــوع ‪ .....‬وجــد مبلــف الســتديو عــدد صــور للفتــاة املشــتكية وصــور‬\n‫لفتيــات أخريــات وقــد اســفر التحقيــق عــن اتهــام املدعــى عليــه بإقامــة‬\n‫عالقــة محرمــة مــع فتــاة ال متــت لــه بصلــة شــرعية وتهديدهــا و ابتزازهــا‬\n\n\n                                                                                        ‫‪96‬‬\n\f     ‫بنشــر صورهــا وتخزيــن و إرســال مــا مــن شــأنه املســاس بــاآلداب العامــة‬\n     ‫وحرمــة احليــاة اخلاصــة بهاتفهــا اجلــوال وذلــك لألدلــة و القرائــن التاليــة‪:‬‬\n     ‫‪ /1‬مــا ورد بأقوالــه ‪/2‬مــا ورد مبحضــر القبــض ‪ /3‬مــا ورد مبحضــر‬\n     ‫تفريــغ الرســائل ‪ /4‬مــا ورد مبحضــر االطــاع و املشــاهدة ألجهــزة‬\n     ‫اجلــوال املضبوطــة مــع املتهــم لــذا اطلــب إثبــات مــا اســند اليــه و احلكــم‬\n     ‫عليــه باآلتــي ‪/ :‬الســجن والغرامــة أو بأحدهمــا ملــا ورد يف املــادة (‪ )6‬مــن‬\n     ‫نظــام اجلرائــم املعلوماتيــة ‪/2‬مصــادرة اجلــوال مــن نــوع ‪ ......‬رقــم (‪)..........‬‬\n     ‫و اجلــوال مــن نــوع‪ ..........‬و جــوال مــن نــوع ‪ .....‬رقــم (‪)..........‬اســتناد ًا‬\n     ‫للمــادة الثالثــة عشــر مــن نظــام اجلرائــم املعلوماتيــة ‪ /3‬بعقوبــة تعزيريــة‬\n     ‫مشــددة لقــاء أقامتــه عالقــة محرمــة بامــرأة ال متــت لــه بصلــة شــرعية‬\n     ‫(علمـ ًا أن احلــق اخلــاص ال زال قائمـاً) هــذه دعــواي ‪ .‬وبعــرض ذلــك علــى‬\n     ‫ا ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه علــي مــن‬  ‫املدعــى عليــه أجــاب قائـ ً‬\n     ‫حيــث اقامــة عالقــة محرمــة عــن طريق الهاتــف والرســائل وتهديدها عن‬\n     ‫طريــق الرســائل صحيــح وباالطــاع علــى املعاملــة وجــد إقــرار املدعيــة‬\n     ‫باحلــق اخلــاص بأنهــا متنازلــة عــن حقهــا اخلــاص وال تطالــب املدعــى عليــه‬\n     ‫بــأي شــيء ومذيــل بتوقيعهــا وتوقيــع معرفهــا وشــاهدين عليهــا وباالطالع‬\n     ‫علــى كــرت الســوابق لــم يعثــر لــه علــى ســوابق وبنــاء علــى مــا تقــدم مــن‬\n     ‫الدعــوى واالجابــة واملتضمنــة االقــرار بإقامــة عالقــة محرمــة مــع فتــاة‬\n     ‫عــن طريــق الهاتــف وتهديدهــا وابتزازهــا بنشــر صورهــا إلجبارهــا علــى‬\n     ‫اخلــروج معــه وخيانــة عرضهــا وأهلهــا وبنــاء علــى تنــازل املدعيــة باحلــق‬\n     ‫اخلــاص وبنــاء علــى عــدم وجــود ســوابق للمدعــى عليــه وألن مــا أقــدم عليه‬\n     ‫املدعــى عليــه أمــر عظيــم وجــرم كبيــر يســتحق عليهــا العقوبــة الشــديدة‬\n     ‫والرادعــة ألنــه ميــس ضــرورة مــن الضــرورات اخلمــس وهــي حفــظ العرض‬\n\n\n‫‪97‬‬\n\f‫وملــا يترتــب علــى عملــه الشــنيع مــن انتهــاك لألعــراض احملرمــة التــي أمــر‬\n‫اهلل بحفظهــا وملــا يترتــب عليــه مــن شــيوع الفاحشــة يف اللذيــن امنــوا التي‬\n‫حــذر اهلل منهــا بقولــه ‪ ( :‬ان الذيــن يحبــون ان تشــيع الفاحشــة يف اللذيــن‬\n‫امنــوا لهــم عــذاب أليــم يف الدنيــا واألخــرة ) وحيــث لــم يقتصــر األمــر‬\n‫علــى العالقــة احملرمــة بــل تعــدى ذلــك إلــى ابتزازهــا وتهديدهــا وبنــاء‬\n‫علــى نظــام مكافحــة اجلرائــم املعلوماتيــة املــادة الثالثــة واملــادة السادســة‬\n‫واملــادة الثالثــة عشــر فقــد ثبــت لــدي إدانــة املدعــى عليــه بإقامــة عالقــة‬\n‫محرمــة مــع فتــاة وتهديدهــا بنشــر صورهــا وحكمــت عليــه لقــاء ذلــك‬\n‫بســجنه ملــدة ســنة تبــدء مــن تاريــخ إيقافــه علــى ذمة هــذه القضيــة وغرامة‬\n‫ماليــة قدرهــا عشــرة آالف ريــال وجلــده خمســن جلــدة تكــرر عليــه‬\n‫عشــر مــرات الفاصــل بينهــا شــهر ًا وإقامــة اجللــد أمــام جامعــة البنــات‬\n‫مــرة واحــدة بعــد الظهــر ومصــادرة اجلــوال مــن نــوع ‪ .....‬رقمــه التسلســلي‬\n‫‪ ..........‬واجلــوال مــن نــوع ‪ ......‬رقمــه التسلســلي رقــم ‪ ..........‬وجــوال مــن‬\n‫نــوع ‪ .....‬رقمــه ‪..........‬وماذكــره املدعــي العــام مــن طلــب عقوبــة تعزيريــة‬\n‫مشــددة لقــاء إقامــة عالقــه محرمــة هــي داخلــة يف العقوبــة الســابقة‬\n‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم وأمــا املدعــي‬\n‫العــام فقــرر االعتــراض بالئحــة اعتراضيــة فجــرى إفهامــه بتعليمــات‬\n‫االســتئناف وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1434/3/1‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/4/9‬ه ـ‬\n‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n‫قــرار الدائــرة اجلزائيــة االولــى رقــم (‪ )3463319‬يف ‪1434/3/16‬ه ـ‬\n‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪،‬‬\n           ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/4/9‬ه ـ ‪.‬‬\n\n\n                                                                                         ‫‪98‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":93,"source_page_end":98,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"21455538ef400894e655dc7a0f7a2508041c28afd7ce30716c1d05a6206535bc","normalized_text_hash":"7ff473cf1e8d7a8c7692323a33b3867073ac25dea5f2a31287fec06a9119ad99","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p93-3451637"},{"id":"bd29cffd-e76c-5d7f-8c00-8f0b2f9bb3fe","document_type":"judgment","category":"judicial","subcategory":"general","title":"إبتزاز -ابتزاز فتاة مالي ا -تهديد بنشر صور -خلوة محرمة - إقامة عالقة محرمة مع فتاة -جرائم معلوماتية -تشديد العقوبة التعزيرية النتشار اجلرمية يف املجتمع -عدم وجود سابقة موجب لتخفيف العقوبة -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمة ووعظ املدعى عليه .","document_number":"34238176","case_number":"3481021","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/18","year":"1434","subject":"إبتزاز -ابتزاز فتاة مالي ا -تهديد بنشر صور -خلوة محرمة - إقامة عالقة محرمة مع فتاة -جرائم معلوماتية -تشديد العقوبة التعزيرية النتشار اجلرمية يف املجتمع -عدم وجود سابقة موجب لتخفيف العقوبة -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمة ووعظ املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34238176:‬تاريخه‪1434/02/18 :‬هـ‬\n                           ‫رقم الدعوى‪3481021:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34238176‬تاريخه‪1434/06/12 :‬هـ‬\n\n\n      ‫إبتــزاز ‪ -‬ابتــزاز فتــاة مالي ـ ًا ‪ -‬تهديــد بنشــر صــور ‪ -‬خلــوة محرمــة ‪-‬‬\n      ‫إقامــة عالقــة محرمــة مــع فتــاة ‪ -‬جرائــم معلوماتيــة ‪ -‬تشــديد العقوبــة‬\n      ‫التعزيريــة النتشــار اجلرميــة يف املجتمــع ‪ -‬عــدم وجــود ســابقة موجــب‬\n      ‫لتخفيــف العقوبــة ‪ -‬تعزيــر بالســجن واجللــد ومصــادرة اجلــوال‬\n                                ‫والشــريحة املســتخدمة ووعــظ املدعــى عليــه ‪.‬‬\n\n\n\n\n                                  ‫‪ -1‬املادة الثالثة من نظام اجلرائم املعلوماتية‪.‬‬\n                                ‫‪ -2‬املادة السادسة من نظام اجلرائم املعلوماتية‪.‬‬\n                                            ‫‪ -3‬ما أشير له يف احلكم من تسبيب‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن االدعــاء العــام علــى املدعــى عليــه بابتــزاز فتــاة‬\n      ‫للحصــول علــى مبلــغ مالــي وتهديدهــا بنشــر صورهــا بإرســال أربعــة‬\n      ‫عشــر رســالة نصيــة تهديديــة عــن طريــق اجلــوال وتخزيــن مــا مــن شــأنه‬\n      ‫املســاس بحرمــة احليــاة اخلاصــة وطلــب احلكــم عليــه بالســجن والغرامــة‬\n      ‫ومصــادرة اجلــوال والذاكــرة املســتخدمة وفقــا لنظــام مكافحــة‬\n      ‫اجلرائــم املعلوماتيــة ‪ ،‬حيــث تقدمــت فتــاة بشــكوى ملركــز هيئــة األمــر‬\n      ‫باملعــروف بأنهــا تعرفــت علــى املدعــى عليــه ونشــأت بينهمــا عالقــة عبــر‬\n\n‫‪99‬‬\n\f‫الهاتــف إال أنهــا ملــا عزمــت علــى إنهــاء العالقــة أخــذ يبتزهــا وطلــب‬\n‫منهــا مبالــغ ماليــه ويهددهــا بنشــر صورهــا احملفوظــة لديــه فأعــد لــه‬\n‫كمــن فقبــض عليــه وجهــاز اجلــوال الصــادر منــه الرســائل بحوزتــه‬\n‫وجــرى تفريــغ الرســائل الــواردة للمشــتكية مــن جوالهــا املشــتملة علــى‬\n‫التهديــد واالبتــزاز ‪ ،‬أنكــر املدعــى عليــه التهمــة ودفــع بــأن العالقــة‬\n‫معهــا كان ألجــل توصيلهــا وأهلهــا ملشــاوير وأنــه ملــا طالبهــا بأجرتــه‬\n‫املتراكمــة خمســة آالف ريــال أرســلت لهــا صورهــا إلغرائــه ‪ ،‬فهددهــا‬\n‫بأنهــا إن لــم تعطــه أجرتــه فسينشــر صورهــا وبنــاء علــى إقــرار املدعــى‬\n‫عليــه بالتهديــد واحتــواء جــوال املدعــى عليــه علــى صــور املشــتكية‬\n‫وشــهادة الشــاهدين ومحضــر القبــض ومحضــر تفريــغ جــوال املشــتكية‬\n‫ومــا تضمنتــه الرســائل مــن ابتــزاز والنتشــار مثــل هــذه اجلرميــة يف املجتمــع‬\n‫وخلطــورة التســاهل يف األعــراض ممــا يســتوجب تشــديد العقوبــة إال أنــه‬\n‫ال توجــد عليــه ســوابق ‪ ،‬كمــا انــه أثبــت القاضــي إدانــة املدعــى عليــه‬\n‫بابتــزاز فتــاة للخــروج معــه واحلصــول علــى مبلــغ مالــي منهــا وتهديدهــا‬\n‫بنشــر صورهــا وتخزيــن مــا مــن شــأنه املســاس باحلرمــة اخلاصــة واحلكــم‬\n‫عليــه بســجنه ســنة مــن تاريــخ إيقافــه وجلــده ثالثمئــة جلــدة مفرقــة علــى‬\n‫دفعــات متســاوية يف العــدد بــن كل دفعــة والتــي تليهــا مــدة ال تقــل عــن‬\n‫أســبوع ‪ ،‬ومصــادرة اجلــوال وذاكرتــه والشــريحة املســتخدمة وعــدم‬\n‫صرفهــا لــه مــرة أخــرى إيــداع قيمتــه يف اخلزينــة العامــة حلســاب رئاســة‬\n‫الهيئــات كمــا جــرى وعــظ املدعــى عليــه ‪ ،‬قــرر املدعــى عليــه القناعــة‬\n‫باحلكــم بينمــا اعتــرض املدعــى عليــه وأفهــم بتعليمــات االســتئناف ‪،‬‬\n                                    ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n                                                                                       ‫‪100‬‬\n\f      ‫احلمــد هلل وحــده وبعــد يف هــذا اليــوم االثنــن املوافــق ‪1434/3/16‬هـ ـ‬\n      ‫الســاعة التاســعة والنصف صباحا لدي أنا ‪.......... /‬القاضي باحملكمة‬\n      ‫اجلزائيــة بالطائــف وبنــاء علــى املعاملــة املقيــدة برقــم ‪ 34408811‬يف‬\n      ‫‪1434/2/18‬هـ ـ واحملالــة إلينــا برقــم ‪ 3481021‬يف ‪1432/2/18‬هـ ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــى العــام ‪..........‬بالتعميــد رقــم ‪..........‬‬\n      ‫فـ ــي ‪1433/10/18‬هـ ـ وادعــى علـ ــى احلاضــر باملجلــس ‪..........‬ســعودي‬\n      ‫ا أنــه بتاريــخ‬     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬قائ ـ ً‬\n      ‫‪1434/2/5‬ه ـ ورد بــاغ ملركــز شــرطة ‪..........‬محضــر مركــزي هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر ب‪ ..........‬واملتضمــن أن الفتــاة‬\n      ‫ســعودية اجلنســية تبلغ من العمر ‪ 23‬ســنة تدعى ‪..........‬تقدمت بشــكوى‬\n      ‫وترغــب يف الســتر عــن نفســها حيــث ذكــرت يف شــكواها أنهــا تعرفــت‬\n      ‫علــى املدعــى عليــه صاحــب ليموزيــن قبــل شــهرين وكان يقــوم بإيصالها‬\n      ‫لعملهــا ومــكان دراســتها ونشــأت عالقــة بينهمــا حتصــل مــن خاللهــا‬\n      ‫علــى صــور تخصهــا وعندمــا قــررت الفتــاه التوبــة وتــرك العالقــة قــام‬\n      ‫املدعــى عليــه بتهديدهــا بــأن تخــرج معــه ويختلــى بهــا وإال ســيقوم بنشــر‬\n      ‫صورهــا عنــد أهلهــا وعملهــا وكذلــك مقر دراســتها ويف مواقع التواصل‬\n      ‫االجتماعــي مثــل تويتــر وفيــس بــوك وعندمــا امتنعــت مــن اخلــروج معــه‬\n      ‫أخــذ يطلــب منهــا مبلــغ وقــدره (‪ )5000‬خمســة آالف ريــال ســعودي‬\n      ‫مقابــل مســح صورهــا فرفضــت ذلــك ألنهــا المتلــك املبلــغ وطلبــت منــه‬\n      ‫تخفيــض املبلــغ وإمهالهــا بعــض الوقــت لتوفيــر املبلــغ ولكنهــا لــم‬\n      ‫تســتطيع ويف يــوم األربعــاء املوافــق ‪1434/1/28‬ه ـ حضــر املدعــى عليــه‬\n\n‫‪101‬‬\n\f‫أمــام مقــر عمــل الفتــاه وطلــب منهــا الركــوب معــه لتمســح صورهــا‬\n‫بنفســها وحلــف لهــا بــاهلل العظيــم بأنــه صــادق معهــا ‪ ،‬فركبــت معــه يف‬\n‫ســيارته الليموزيــن وقامــت مبســح صورهــا املوجــودة يف البرنامج الواتس‬\n‫اب ‪ ،‬ولكنــه حتــرك بســيارته وذهــب بهــا إلــى إحــدى االســتراحات‬\n‫واختلــى بهــا وتركهــا بعــد ذلــك يف االســتراحة وأعادهــا ‪.......... /‬وحــاول‬\n‫ربــط عالقــة معهــا وأعطاهــا رقــم جوالــه وبتفريــغ الرســائل الــواردة يف‬\n‫جــوال الفتــاه وجــد أنهــا حتتــوى علــى تهديــد صريــح مــن املدعــى عليــه‬\n‫وقامــت الفتــاه بإرســال صــورة شــخصية املدعــى عليــه وطلــب أعضــاء‬\n‫الهيئــة منهــا املوافقــة علــى طلــب املدعــى عليــه وأن تقــوم بإيهامــه بأنهــا‬\n‫ســتخرج معــه فاتفقــت معــه أن يحضــر إلركابهــا يــوم االثنــن املوافــق‬\n‫‪1434/2/4‬ه ـ عنــد ‪..........‬التــي تــدرس بهــا الفتــاه عنــد الســاعة الثانيــة‬\n‫عشــر ظهــر ًا وهــو وقــت انصرافهــا ويف الوقــت والزمــان املتفــق عليــه‬\n‫حضــر املدعــى عليــه وتوقــف بالقــرب مــن ‪..........‬وبإقتــراب الهيئــة مــن‬\n‫املدعــى عليــه مت التعــرف عليــه فتــم اســتيقافه ومت االتصــال علــى الرقــم‬\n‫الــذي وردت منــه رســائل التهديــد فــإذا اجلــوال بيــده فتــم القبــض عليــه‬\n‫وبســؤاله عــن دعــوى الفتــاه أخــذ يطلــب الســتر عليــه وأفــاد بصحــة‬\n‫اإلخباريــة وبتفتيــش جــوال املدعــى عليــه املضبــوط معــه نــوع ‪ ......‬أســود‬\n‫اللــون رقــم التسلســلي ( ‪ )..........‬شــوهد بــه عــدة صــور للفتــاة ووجــدت‬\n‫رســائل التهديــد ‪ .‬وبتفريــغ الرســائل الــواردة جلــوال الفتــاه املشــتكية مــن‬\n‫جــوال املدعــى عليــه رقــم(‪ )..........‬اتضــح أن بــه الرســائل التاليــة ‪-1‬‬\n‫رســالة نصيــة أرســلت بتاريــخ ‪2012/11/25‬م الســاعة ‪11،42‬م أرســلت‬\n‫عــن طريــق برنامــج ‪ .....‬ونصهــا ( نطلــع ســوى فهمتــي علــي ابيــك تــويف‬\n‫بكالمــك فخرجتنــا وبــس )‪ -2‬رســالة نصيــة أرســلت بتاريــخ‬\n\n\n                                                                                      ‫‪102‬‬\n\f      ‫‪2012/11/25‬م الســاعة ‪11،44‬م أرســلت عــن طريــق برنامــج ‪.....‬‬\n      ‫ونصهــا ( بــس أبيــك تخرجــي معايــه وبنــام معــاك وأعاهدكــي بــاهلل‬\n      ‫مااضــرك والابــي اجرحــك انتــي مــن حدنــي علــى هالشــي خالنــي اخــرج‬\n      ‫عــن صوبــي اســتغفر اهلل تبــن احلــل الثانــي رافضــة اخلرجــة قولــي انــا‬\n      ‫اكلمــك )‪ -3‬رســالة نصيــة ارســلت بتاريــخ ‪2012/11/25‬م الســاعة‬\n      ‫‪11،45‬م عــن طريــق برنامــج ‪ .....‬ونصهــا ( والاخــرج ماتبــن األول مــا‬\n      ‫عجبــك ابــي مبلــغ فلــوس دفــع ثمــن لضحكتــك ومشــورتك فينــي‬\n      ‫وكذبــك وغــدرك بحبــك اللــي اتصنعتيــه وبعدهــا روحــي يف حالــك )‬\n      ‫‪ -4‬رســالة نصيــة ‪2012/11/25‬م الســاعة ‪11،47‬م عــن طريــق برنامــج‬\n      ‫‪ .....‬ونصهــا (خمســة آالف تقــدري وال ال حتوليهــا علــى حســابي متــى‬\n      ‫يعنــي ابيهــا هاليومــن كــم عنــدك يعنــي واتــركك فحالــك صدقينــي‬\n      ‫مــا ابــي اضــرك وال ابــي منــك شــي لكــن ذي جــزاة كالمــك انتــي مــن‬\n      ‫حدني على ها الشــي ) ‪ -5‬رســالة نصية أرســلت بتاريخ ‪2012/11/25‬م‬\n      ‫الســاعة ‪11،49‬م عــن طريــق برنامــج ‪ ......‬ونصهــا (ترســلي لــي وال ال‬\n      ‫تقدريــن هــل يومــن وإال ال اصلــح اللــي يف راســي كــم معــاك واعــذرك‬\n      ‫بالباقــي) ‪ -6‬رســالة نصيــة بتاريــخ ‪2012/11/25‬م الســاعة ‪ 11،58‬م‬\n      ‫عــن طريــق ‪ .....‬ونصهــا (لــو االربعــاء مــا احصلهــا يف حســابي التتعبــي‬\n      ‫حالــك وترســليها النــي مبشــي الــي براســي طيــب ‪..........‬ثالثــة خــاص‬\n      ‫اتفقنــا االربعــاء اســم صاحــب احلســاب ‪ -..........‬رســالة نصيــة أرســلت‬\n      ‫بتاريــخ ‪2012/11/25‬م الســاعة ‪11،32‬م عــن طريــق برنامج ‪ .....‬ونصها‬\n      ‫( بيتــك واعــرف واعــرف فــن تشــتغلني قســم الســود عيشــتك ياعبــده‬\n      ‫فاهمــه )‪ -8‬رســالة نصيــة بتاريــخ ‪2012/11/25‬م الســاعة ‪11،32‬م عــن‬\n      ‫طريــق البرنامــج ‪ .......‬ونصهــا (واهلل ألنســخها وال أطبعهــا علــى بوابــة ‪.....‬‬\n\n\n‫‪103‬‬\n\f‫وبــال‪ .....‬وال أخلــي تشــوتك مــع البــاب مــن بكــرة ) ‪ -9‬رســالة نصيــة‬\n‫أرســلت بتاريــخ ‪2012/11/25‬م الســاعة ‪11،34‬م أرســلت عــن طريــق‬\n‫برنامــج ‪ ......‬ونصهــا ( طيــب طيــب بكــره أفرجــك اقلبــي وجهــك‬\n‫وصــورك بتحصليهــا فــكل زاويــة وبنزلهــا بالفيــس وتويتــر مــو انتــي‬\n‫ياعبــده اللــي تقولــي لواحــد يف مثابتــي ومســتواي مابيــك ) ‪ -10‬رســالة‬\n‫نصيــة أرســلت بتاريــخ ‪2012/11/25‬م الســاعة ‪11،34‬م عــن طريــق‬\n‫برنامــج ‪ .....‬ونصهــا (اوعــدك اســود عيشــتك االمبقابــل واال بصلــح الــي‬\n‫براســي طيــب) ‪ -11‬رســالة نصيــة أرســلت بتاريــخ ‪2012/11/25‬م‬\n‫الســاعة ‪11،35‬م أرســلت عــن طريــق برنامــج ‪ .......‬ونصهــا ( أرســل‬\n‫صــورة الفتــاة ) ( تصدقــي مــرة حلــوة هههههــه ســاعة بــس أدخلــي تويتــر‬\n‫بالصفحــة الرئيســية ) هيــا انقلعــي بصلــح الــي بيجــي علــى بالــي وبتفــن‬\n‫بعــد وبدقــه ال تقولــي ماقلتلــي ‪ -12 .‬رســالة نصيــة أرســلت بتاريــخ‬\n‫‪2012/11/25‬م الســاعة ‪11:37‬م أرســلت عــن طريــق برنامــج ‪......‬‬\n‫ونصها(كلــي تــن فاهمــة مــو انتــي اللــي تخيرينــي بــو جــودي معــك خلــي‬\n‫كبرتــك تنفعــك اال مبقابــل تصلحيــة امســح لــك صــوره واهلل واهلل ال‬\n‫علقهــا علــى بوابــة ‪ ....‬لطبعهــا طباعــة وأوعــدك و انســخها مــن النــت مــن‬\n‫عنــدي واصورهــا وارســلها لــك ) ‪ -13 .‬رســالة نصيــة أرســلت بتاريــخ‬\n‫‪2012/11/25‬م الســاعة ‪11،38‬م أرســلت عــن طريــق برنامــج ‪........‬‬\n‫ونصهــا ( تخرجــي معايــه مــو تضحكــي عليــا وتأخذينــي علــى نيتــي شــو‬\n‫رايــك ) ‪ -14 .‬رســالة نصيــة أرســلت بتاريــخ ‪2012/11/25‬م الســاعة‬\n‫‪11،40‬م أرســلت عن طريق برنامج ‪ .......‬ونصها (نطلع ســوى واعاهدك‬\n‫بــاهلل بعدهــا كل واحــد يــروح يف حالــه وال اغــدرك وال اضــرك بــس‬\n‫ابيــك نفســي فيــك وبــس واذا رافضــه قوليلــي انتــي مــن طلعنــي وجبرنــي‬\n\n\n                                                                                   ‫‪104‬‬\n\f      ‫اصلــح ذا الشــي ) ‪ .‬ومبشــاهدة جــوال املتهــم املضبــوط معــه وجــد بــه عــدد‬\n      ‫أربــع صــور تخــص الفتــاة يظهــر بهــا وجههــا وأجــزاء مــن جســمها ‪ .‬وصــدر‬\n      ‫أمــر حجــز مضبوطــات للجهــاز اجلــوال املضبــوط مــع املتهــم نوعــه ‪......‬‬\n      ‫اســود اللــون رقمــه التسلســلي‪ ..........‬والذاكــرة الفــاش ميمــوري‬\n      ‫وشــريحة االتصــال املســتخدمة يف إرســال الرســائل ‪ .‬ومت فــرز أوراق‬\n      ‫مســتقلة فيمــا يتعلــق بإقامــة املتهــم املذكــور ورفيقــه ‪..........‬عالقــة‬\n      ‫محرمــة مــع فتــاة واســتدراجها لالســتراحة واالختــاء بهــا لعــدم‬\n      ‫اختصــاص دائــرة املــال بهــا وكــون دائــرة التحقيــق يف قضايــا العــرض‬\n      ‫واالخــاق لــم تباشــر أعمالهــا مبحافظــة الطائــف حاليــا وفقــا خلطــاب‬\n      ‫ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام بالطائــف رقــم (‪)..........‬‬\n      ‫وتاريــخ ‪1434/2/6‬ه ـ واملوجــه لســعادة مديــر شــرطة الطائــف ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه أقــر بإقامــة عالقــة محرمــة مــع الفتــاة ‪/‬‬\n      ‫‪..........‬حيــث تعــرف عليهــا قبــل شــهر ونصــف تقريبـ ًا عن طريــق التوصيل‬\n      ‫بالســيارة وراســلته وراســلها عــن طريــق برنامــج ‪ ....‬وهــي ال متــت لــه بــأي‬\n      ‫صلــة عالقــة أو قرابــة شــرعية وأنكــر االختــاء بهــا وأقــر بوجــود‬\n      ‫صورتــن شــخصيتني للفتــاة املشــتكية يف جوالــه املضبــوط معــه ونوعــه‬\n      ‫‪ .....‬وأقــر بإرســال رســالتني نصيتــن الــواردة يف محضــر هيئــة األمــر‬\n      ‫باملعــروف والنهــي عــن املنكــر ونصهــا التالــي ( وال اخــرج مــا تبــن االول‬\n      ‫مــا عجبــك ابــي مبلــغ فلــوس دفــع ثــم ضحكتــك ومشــورتك فينــي‬\n      ‫وكذبــك وغــدرك بحبــك اللــي اتصنعتيــه وبعدهــا روحــي يف حالــك )‬\n      ‫والرســالة الثانيــة نصهــا ( خمســة آالف تقديــري وال ال حتوليهــا علــى‬\n      ‫حســابي متــى يعنــي أبيهــا هاليومــن كــم عنــدك يعني واتــركك فحالك‬\n      ‫صدقينــي مــا أبــي أضــرك وال ابــي منــك شــي لكــن ذي جــزاة كالمــك‬\n\n\n‫‪105‬‬\n\f‫انتــي مــن حدنــي علــى هالشــي ) وأنكــر االختــاء بالفتــاة ‪ .‬وقــد أســفر‬\n‫التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بابتــزاز فتــاة للحصــول علــى‬\n‫مبلــغ مالــي وتهديدهــا بنشــر صورهــا بارســال رســائل عــن طريــق اجلــوال‬\n‫وتخزيــن مــا مــن شــانه املســاس بحرمــة احليــاة اخلاصــة وذلــك لألدلــة‬\n‫والقرائــن التاليــة ‪ -1 :‬إقــراره املنــوه عنهــا واملدونــه مبلــف التحقيــق ‪-2 .‬‬\n‫محضــر القبــض املنــوه عنــه واملرفــق بــاألوراق ‪ - 3 .‬مــا ورد مبحضــر‬\n‫تفريــغ جــوال املــرأة املشــتكية مــن قبــل هيئــة األمــر باملعــروف والنهــي‬\n‫عــن املنكــر املنــوه عنــه واملرفــق بــاألوراق ‪ -4 .‬مــا ورد مبحضــر مشــاهدة‬\n‫جــوال املتهــم واملتضمــن مشــاهدة صــورة الفتــاة املنــوه عنهــا واملرفــق‬\n‫بــاألوراق ‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا ومعاقــب عليــه وفق ـ ًا‬\n‫لنــص املــادة السادســة مــن نظــام مكافحــة اجلرائــم املعلوماتيــة الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )17/‬وتاريــخ ‪1428/3/8‬ه ـ لــذا أطلــب إثبــات‬\n‫ما أســند إليه واحلكم عليه باآلتي ‪ -1 :‬الســجن والغرامة أو بإحداهما‬\n‫وفقـ ًا ملــا ورد يف املــادة السادســة مــن نظــام مكافحــة اجلرائــم املعلوماتيــة‬\n‫‪ -2 .‬مصــادرة جهــاز جــوال مــن نــوع ‪ ......‬أســود اللــون رقمــه التسلســلي‬\n‫(‪ )..........‬والذاكــرة اخلاصــة بــه وشــريحة االتصــال املســتخدمة يف‬\n‫اجلرميــة اســتناد ًا للمــادة الثالثــة عشــرة مــن نظــام اجلرائــم املعلوماتيــة‬\n‫املشــار إليــه ‪ .‬علمـ ًا بــأن احلــق اخلــاص مــازال قائمـ ًا هــذه دعــواي ‪ .‬وبعــرض‬\n‫ذلــك علــى املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام مــن‬\n‫اتهامــي بابتــزاز فتــاة للحصــول علــى مبلــغ مالــي وتهديدها بنشــر صورها‬\n‫فغيــر صحيــح والصحيــح أن عالقتــي مــع الفتــاة بقصــد توصيلهــا هــي‬\n‫وأهلهــا إلــى املشــاوير فقــط وكنــت أطالبهــا مببلــغ التوصيــل ألنهــا‬\n\n\n                                                                                          ‫‪106‬‬\n\f      ‫وأهلهــا ماطلــوا بــي حتــى أصبــح املبلــغ خمســة آالف ريــال وعنــد إحلاحــي‬\n      ‫باملطالبــة باملبلــغ بــدأت بإرســال صورهــا لــي مــن بــاب اإلغــراء فأرســلت‬\n      ‫لهــا عــدة رســال تتضمــن أنهــا إذا لــم تعطينــي حقــي فســوف أقــوم بنشــر‬\n      ‫صورهــا ولــم يكــن قصــدي القيــام بذلــك ولكــن مــن بــاب الضغــط‬\n      ‫عليهــا الســتخالص حقــي ‪ ،‬وبالتالــي فلــم يكــن بينــي وبينهــا أي عالقــة‬\n      ‫ســوى ذلــك ولــم أختلــي بهــا والصــور التــي لهــا يف جوالــي هــي التــي قامــت‬\n      ‫بإرســالها لــي هكــذا أجــاب ‪ .‬وبنــاء علــى ذلــك فقــد رفعــت اجللســة لطلــب‬\n      ‫أعضــاء هيئــة األمــر باملعــروف والنهــي عــن املنكــر للتحقــق مــن إقــرار‬\n      ‫املدعــى عليــه أمامهــم عنــد القبــض عليــه بصحــة اإلخباريــة وطلب الســتر‬\n      ‫عليــه ‪ .‬ثــم يف يــوم اإلثنــن املوافــق‪ 1434/03/23‬ه ـ افتتحــت اجللســة‬\n      ‫وفيهــا حضــر املدعــي عليــه كمــا حضــر أعضــاء هيئــة االمــر باملعــروف‬\n      ‫والنهــي عــن املنكــر‪ .......... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ )..........‬و‪ ....................‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ( ‪ )..........‬وبســؤالهما عمــا لديهمــا مــن شــهادة شــهدا قائلــن ‪:‬‬\n      ‫نشــهد هلل تعالــى أنــه عنــد القبــض علــى املدعــى عليــه أقــر أمامنــا بــأن‬\n      ‫حضــوره لألكادميــة بقصــد أخــذ الفتــاه املشــتكيه وطلــب الســتر منــا‬\n      ‫عليــه وبعــد القبــض عليــه وتفتيــش جوالــه وجدنــا يف جوالــه الرســائل‬\n      ‫املذكــورة يف محضــر تفريــغ الرســائل واملتضمنــة طلبــه منهــا اخلــروج‬\n      ‫معــه وتهديدهــا بفضحهــا إن لــم تخــرج معــه وطلبــه منهــا مبلــغ مالــي‬\n      ‫وتهديدهــا إذا لــم تســتجب لــه هكــذا شــهدا كمــا أضــاف الشــاهد‬\n      ‫األول بقولــه‪ :‬كمــا أن جــوال املدعــى عليــه يحتــوي علــى صــور للفتــاه يف‬\n      ‫مقــر ســكنه وقــد عرفــت ذلــك لذهابــي إلــى ســكنه بســبب الشــخص‬\n      ‫اآلخــر الــذي قبــض عليــه معــه ولوجــود صــور أخــرى للمدعــى عليــه وهــو‬\n\n\n‫‪107‬‬\n\f‫داخــل ســكنه هكــذا أضــاف وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n‫بقولــه ‪ :‬ال أقــدح يف الشــاهدين وأمــا مــا جــاء يف شــهادتهما فغيــر صحيــح‬\n‫هكــذا أجــاب‪ .‬فبعــد ســماعي للدعــوى واإلجابــة ‪ ،‬ومــا ورد يف شــهادة‬\n‫أعضــاء هيئــة االمــر باملعــروف والنهــي عــن املنكــر ‪ ،‬وألن املدعــى عليــه‬\n‫أقــر بتهديــده للفتــاه بنشــر صورهــا ‪ ،‬واحتــواء جوالــه علــى صــور لهــا وأنه‬\n‫ا ذلــك مبــا جــاء يف جوالــه ‪ ،‬وألن مــا دفــع بــه ال‬\n                                                       ‫لــم يقــم مبســحها معل ـ ً‬\n‫يســوغ لــه القيــام بذلــك ‪ ،‬وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا‬\n‫محضــر القبــض ‪ ،‬ومحضــر تفريــغ جــوال املشــتكية ‪ ،‬ومحضــر‬\n‫مشــاهدة جــوال املتهــم املشــار إلــى مضمونهــا يف الدعــوى ‪ ،‬وألن بعــض‬\n‫الرســائل املذكــورة يف احملاضــر تــدل علــى أن التهديــد بقصــد طلــب‬\n‫خروجهــا معــه أيضــا ‪ ،‬وخلطــورة التســاهل يف أمــر األعــراض واالســتهتار‬\n‫بذلــك ‪ ،‬والنتشــار ظاهــرة االبتــزاز يف املجتمــع ‪ ،‬ممــا يلــزم معــه تشــديد‬\n‫العقوبــة علــى مــن يثبــت بحقــه ذلــك ‪ ،‬وبنــاء علــى املادتــن الثالثــة‬\n‫والسادســة مــن نظــام مكافحــة اجلرائــم املعلوماتيــة ‪ ،‬ولعــدم وجــود‬\n‫ســوابق للمدعــى عليــه ‪ ،‬لهــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه‬\n‫بابتــزاز فتــاة للخــروج معــه وللحصــول علــى مبلــغ مالــي منهــا وتهديدهــا‬\n‫بنشــر صورهــا وتخزيــن مــا مــن شــأن املســاس بحرمــة احليــاة اخلاصــة ‪،‬‬\n‫وحكمــت عليــه لقــاء ذلــك بســجنه ســنة كاملــة مــن تاريــخ إيقافــه ‪،‬‬\n‫وجلــده ثالثمائــة جلــدة مفرقــة علــى خمســة دفعــات متســاوية يف العــدد‬\n‫بــن كل دفعــة وأخــرى مــدة ال تقــل عــن أســبوع ‪ ،‬ومصــادرة اجلــوال‬\n‫املضبــوط معــه واملشــار إليــه يف الدعــوى وذاكرتــه وشــريحة االتصــال‬\n‫املســتخدمة يف اجلرميــة وعــدم صرفهــا للمســتخدم مــرة أخــرى وإيــداع‬\n‫قيمــة اجلــوال وذاكرتــه يف حســاب الرئاســة العامــة لهيئــات االمــر‬\n\n\n                                                                                     ‫‪108‬‬\n\f      ‫باملعــروف والنهــي عــن املنكــر ‪ ،‬كمــا جــرى وعــظ املدعــى عليــه‬\n      ‫وتخويفــه بــاهلل تعالــى وتذكيــره بخطــورة فعلــه وأثــره علــى املجتمــع ‪،‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه قــرر القناعــة وأمــا املدعــي العــام فقــرر‬\n      ‫االعتــراض بالئحــة فجــرى إفهامــه بتعليمــات االســتئناف وصلــى اهلل‬\n      ‫وســلم علــى ســيدنا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف‬\n      ‫‪1434/3/23‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق‬\n      ‫‪1434/6/26‬ه ـ افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف وبرفقهــا قــرار الدائــرة اجلزائيــة الثانيــة رقــم (‪)34238176‬‬\n      ‫يف ‪1434/6/12‬ه ـ املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلومية جرى‬\n      ‫حتريــر ذلــك ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف‬\n                                                                          ‫‪1434/6/26‬هـ‬\n\n\n\n\n‫‪109‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":99,"source_page_end":109,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"57a2b3eabe6220e24be9d975bf1c414fa1ca5f9188e9d6e95d1909dea440d6e9","normalized_text_hash":"b129a332b132f6ce5323268d3dbca2d7e952f326e871a12dcbbafe91f77a3840","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p99-34238176"},{"id":"034313ed-53ab-5b30-96b1-07ef9bd81a6f","document_type":"judgment","category":"judicial","subcategory":"general","title":"حيازة مقاطع خليعة ( إباحية ) -جرائم معلوماتية -عدم حضور املدعى عليه بعد طلبه عدة مرات -صرف نظر لعدم حضور املدعى عليه -وضع املدعى عليه على قائمة الترقب.","document_number":"33470421","case_number":"33414189","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/30","year":"1434","subject":"حيازة مقاطع خليعة ( إباحية ) -جرائم معلوماتية -عدم حضور املدعى عليه بعد طلبه عدة مرات -صرف نظر لعدم حضور املدعى عليه -وضع املدعى عليه على قائمة الترقب.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33470421 :‬تاريخه‪1433/11/30 :‬هـ‬\n                     ‫رقم الدعوى‪33414189:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3431184‬تاريخه‪1435/2/5 :‬هـ‬\n\n\n ‫حيــازة مقاطــع خليعــة ( إباحيــة ) ‪ -‬جرائــم معلوماتيــة ‪ -‬عــدم حضــور‬\n ‫املدعــى عليــه بعــد طلبــه عــدة مــرات ‪ -‬صــرف نظــر لعــدم حضــور املدعــى‬\n                         ‫عليــه ‪ -‬وضــع املدعــى عليــه علــى قائمــة الترقــب‪.‬‬\n\n\n\n\n                           ‫‪ -1‬املادة ( ‪ ) 141‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n\n ‫جــرى توجيــه االتهــام للمدعــى عليــه بتخزيــن صــور ومقاطــع مرئيــة‬\n ‫جنســية خليعــة مخلــة بــاآلداب العامــة بجهــازه النقــال وطلــب املدعــي‬\n ‫العــام إثبــات مــا أســند إليــه واحلكــم عليــه بالســجن والغرامــة أو بإحــدى‬\n ‫العقوبتــن ‪ -‬حيــث جــرى القبــض عليــه مــن قبــل الدوريــات األمنيــة خالل‬\n ‫حملتهــا فضبــط بجوالــه مقاطــع جنســية مخلــة بــاآلداب أقــر حتقيقــا‬\n ‫بأنــه قــام بتنزيلهــا جلوالــه عبــر الشــبكة العنكبوتيــة ‪ ،‬جــرى تبليــغ‬\n ‫كفيلــه مبوعــد اجللســة إال أن املدعــى عليــه لــم يحضــر ‪ ،‬جــرى مخاطبــة‬\n ‫الشــرطة بإحضــار املدعــى عليــه فعــادت اإلفــادة بأنــه جــرى البحــث عنــه‬\n ‫فلــم يتــم العثــور عليــه وأنــه ورد لهــم كتــاب مديــر اجلــوازات يف احملافظــة‬\n ‫بــأن املدعــى عليــه غــادر البــاد بتأشــيرة خــروج نهائــي ‪ ،‬بنــاء علــى إفــادة‬\n ‫الشــرطة ‪ ،‬وبنــاء علــى املــادة (‪ )141‬مــن نظــام اإلجــراءات اجلزائيــة فقــد‬\n\n                                                                                        ‫‪110‬‬\n\f      ‫قــررت احملكمــة احلكــم بصــرف النظــر عــن دعــوى املدعــي العــام‬\n      ‫وأمــرت بوضــع املدعــى عليــه علــى قائمــة ترقــب الوصــول إلحضــاره إلــى‬\n      ‫احملكمــة عنــد دخولــه إلــى اململكــة ‪ -‬وأفهمــت املدعــي العــام بــأن‬\n      ‫لــه مواصلــة الدعــوى عنــد حضــور املدعــى عليــه ‪ -‬قــرر املدعــى عليــه‬\n      ‫االعتــراض وطلــب رفــع احلكــم إلــى االســتئناف بــدون تقــدمي الئحــة ‪-‬‬\n                                     ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي ‪...........‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 33414189‬وتاريــخ ‪ 1433/06/21‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331156610‬وتاريــخ ‪ 1433/06/21‬ه ـ بشــأن‬\n      ‫دعــوى املدعــي العــام ضــد ‪...........‬يف تخزيــن مقاطــع إباحيــة ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1433/09/12‬ه ـ افتتحــت اجللســة يف الوقــت احملــدد‬\n      ‫لســماعها الســاعة ‪ 01 : 00‬وفيهــا حضــر املدعــي العــام ولــم يحضــر‬\n      ‫املدعــى عليــه وقــد تبلــغ لغيــر شــخصه عــن طريــق كفيلــه ‪...........‬ولذلــك‬\n      ‫رفعــت اجللســة إلعــادة تبليــغ املدعــى عليــه وحــددت اجللســة القادمــة يف‬\n      ‫يــوم األربعــاء املوافــق ‪1433/10/25‬ه ـ الســاعة احلاديــة عشــرة والنصــف‬\n      ‫صباحــا وعليــه حصــل التوقيــع ويف جلســة اخــرى حضــر املدعــي العــام‬\n      ‫ولــم يحضــر املدعــى عليــه ولــم يردنــا مــا يفيــد تبلــغ املدعــى عليــه وال تبلــغ‬\n      ‫مــن ميثلــه ولذلــك فقــد رفعــت اجللســة إلعــادة تبليــغ املدعــى عليــه وحــددت‬\n      ‫اجللســة القادمــة يف يــوم األحــد املوافــق ‪1433/11/28‬ه ـ الســاعة الثامنــة‬\n      ‫صباحــا وعليــه حصــل التوقيــع ويف جلســة أخــرى حضــر املدعــي العــام‬\n\n‫‪111‬‬\n\f‫ولــم يحضــر املدعــى عليــه وقــد جــرى االطــاع علــى الئحــة االدعــاء‬\n‫العــام املقدمــة مــن املدعــي العــام ‪...........‬فوجدتهــا تتضمــن مــا نصــه‬\n‫بصفتــي عضــو ًا يف دائــرة التحقيــق واالدعــاء العــام مبحافظــة ‪.............‬‬\n‫أدعــي علــى ‪ ..........:‬البالــغ مــن العمــر (‪ )36‬عام ـ ًا ‪ ،‬مصــري اجلنســية ‪،‬‬\n‫مبوجــب جــواز الســفر رقــم (‪ ، )...........‬مســلم ‪ ،‬متعلــم ‪ ،‬غيــر متــزوج‬\n‫‪ ،‬بنــاء عــام ‪ ،‬يقيــم مبحافظــة عنيــزة ‪ ،‬أوقــف بتاريــخ ‪1433/5/15‬ه ـ‬\n‫‪ ،‬وأفــرج عنــه بالكفالــة احلضوريــة بتاريــخ ‪1433/5/17‬ه ـ مبوجــب‬\n‫أمــر اإلفــراج رقــم ‪ )...........‬وتاريــخ ‪1433 /5/ 17‬ه ـ ؛ اســتناد ًا للمــادة‬\n‫(‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬فإنــه بتاريــخ ‪1433/5/15‬ه ـ مت‬\n‫القبــض علــى املتهــم املذكــور مــن قبــل دوريــات األمــن مبحافظــة عنيــزة‬\n‫وذلــك مــن خــال تنفيــذ حملــة أمنيــة مشــتركة حيــث عثــر معــه علــى‬\n‫جهــاز هاتــف نقــال مــن نــوع ‪ )……(.......‬بــه مقاطــع جنســية خالعــة‬\n‫مخلــة بــاآلداب العامــة ‪ .‬وباســتجوابه أقـ ّـر بتخزيــن صــور ومقاطــع فيديــو‬\n‫جنســية مخلــة بــاآلداب العامــة يف جهــاز هاتفــه النقــال مــن نــوع ‪ .......‬عــن‬\n‫طريــق االنترنــت ودون إقــراره بذلــك ‪ .‬وباالطــاع واملشــاهدة لهاتــف‬\n‫املتهــم املوصــوف اتضــح وجــود صــور ومقاطــع فيديــو جنســية مخلــة‬\n‫بــاآلداب العامــة مت تخزينهــا فيــه ‪- .‬إجــراءات متخــذة ‪ -‬حجــز هاتــف‬\n‫املتهــم النقــال املوصــوف مبوجــب أمــر حجــز املضبوطــات رقــم ‪...........‬‬\n‫‪...........‬وتاريــخ ‪1433/5/18‬ه ـ وباالطــاع علــى نتيجــة بحــث ســوابقه‬\n‫علــى املســتوى العــام لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة حتــى‬\n‫تاريخــه وملــا أشــير إليــه ‪-:‬أقــرر اتهــام ‪........... /‬بتخزيــن صــور ومقاطــع‬\n‫فيديــو جنســية خالعــة مخلــة بــاآلداب العامــة بجهــاز هاتفــه النقــال مــن‬\n‫نــوع ‪ )......(.....‬يحمــل الرقــم التسلســلي (‪ )...........‬وذلــك لألدلــة والقرائــن‬\n\n\n                                                                                         ‫‪112‬‬\n\f      ‫اآلتيــة ‪1 -:‬ـ قــراره‪ -‬املنــوه عنــه‪ -‬املــدون علــى الصفحــة رقــم (‪ )3‬مــن دفتر‬\n      ‫محاضــر التحقيــق املرفــق لفــة رقــم (‪2 .)9‬ـ محضــر االطــاع واملشــاهدة‬\n      ‫املنــوه عنــه‪ -‬املــدون علــى الصفحــة رقــم (‪ )4‬مــن دفتــر محاضــر التحقيــق‬\n      ‫املرفــق لفــة رقــم (‪3. )9‬ـ محضــر تنفيــذ مهمــة املعــد مــن قبــل دوريــات‬\n      ‫األمــن املنــوه عنــه‪ -‬املرفــق لفــة رقم(‪.)2‬وحيــث إن مــا أقــدم عليــه املتهــم‬\n      ‫املذكــور فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا مبوجــب نظــام مكافحــة‬\n      ‫جرائــم املعلوماتيــة الصــادر باملرســوم امللكــي رقــم (م‪ )17/‬وتاريــخ‬\n      ‫‪1432/3/8‬ه ـ ومعاقــب عليــه نظامـ ًا أطلــب إثبــات إدانتــه مبا أســند إليه‬\n      ‫واحلكــم عليــه بالعقوبــات التاليــة ‪:‬أوالً‪ :‬بالســجن والغرامــة أو بإحــدى‬\n      ‫هاتــن العقوبتــن وفقـ ًا للفقــرة األولــى مــن املــادة (‪ )6‬السادســة مــن نظــام‬\n      ‫مكافحــة اجلرائــم املعلوماتيــة املشــار لــه ثاًنيــا‪ :‬مبصــادرة جهــاز هاتفــه‬\n      ‫النقــال املوصــوف وفقـ ًا للمــادة (‪ )13‬الثالثــة عشــر مــن نظــام مكافحــة‬\n      ‫اجلرائــم املعلوماتيــة املشــار لــه‪ .‬وبــاهلل التوفيــق انتهــت الئحــة اإلدعــاء‬\n      ‫العــام وقــد جــرت مخاطبــة شــرطة عنيــزة إلحضــار املدعــى عليــه يف هــذا‬\n      ‫اليــوم أو اإلفــادة عــن وضعــه وهــل خــرج عــن اململكــة العربيــة الســعودية‬\n      ‫فوردنــا خطــاب شــرطة عنيــزة رقــم ‪...........‬يف ‪1433/10/25‬ه ـ املتضمن‬\n      ‫أنــه جــرى البحــث عــن املدعــى عليــه ولــم يتــم العثــور عليــه وأنــه وردهــم‬\n      ‫كتــاب مديــر جــوازات عنيــزة رقــم ‪...........‬يف ‪1433/10/8‬ه ـ املتضمــن‬\n      ‫أن املدعــى عليــه غــادر البــاد يف تاريــخ ‪1433/10/18‬ه ـ هذا ما تضمنه‬\n      ‫خطــاب الشــرطة وقــد جــرى االطــاع علــى خطــاب اجلــوازات املذكــور‬\n      ‫فوجدتــه يتضمــن أن املدعــى عليــه غــادر البــاد بتأشــيرة خــروج نهائــي‬\n      ‫انتهــى وبنــاء علــى املــادة ‪ 141‬مــن نظــام اإلجراءات اجلزائيــة ونصها إذا لم‬\n      ‫يحضــر املتهــم املكلــف باحلضــور حســب النظــام يف اليــوم املعــن يف ورقة‬\n\n\n‫‪113‬‬\n\f‫ا عنــه يف األحــوال التــي يســوغ‬ ‫التكليــف باحلضــور ولــم يرســل وكي ـ ً‬\n‫وبيناتــه ويرصدهــا يف‬ ‫فيهــا التوكيــل فيســمع القاضــي دعــوى املدعــي ِّ‬\n‫ضبــط القضيــة وال يحكــم إال بعــد حضــور املتهــم وللقاضــي أن يصــدر‬\n‫أمــر ًا بإيقافــه إذا لــم يكــن تخلفــه لعــذر مقبــول انتهــى وألنــه ال يوجــد‬\n‫يف املعاملــة مــا يفيــد تبلــغ املدعــى عليــه بســبب خروجــه مــن اململكــة‬\n‫ونظــرا إلــى أن هــذه املــادة نصــت علــى أن احلكــم ال يكــون إال بحضــور‬\n‫املتهــم ولكــون املدعــى عليــه خــرج مــن اململكــة خروجــا نهائيــا حســب‬\n‫خطــاب اجلــوازات وملــا تقــدم كلــه فقــد صرفــت النظــر عــن دعــوى‬\n‫املدعــي العــام وأمــرت بوضــع املدعــى عليــه علــى قائمــة ترقــب الوصــول‬\n‫إلحضاره ـ إلــى احملكمــة عنــد دخولــه إلــى اململكــة وأفهمــت املدعــي‬\n‫العــام بــأن لــه مواصلــة الدعــوى عنــد حضــور املدعــى عليــه ومبــا تقــدم‬\n‫حكمــت وبعــرض احلكــم علــى املدعــي العــام قــرر عــدم القناعــة وطلــب‬\n‫اإلســتئناف بــدون الئحــة اعتراضيــة فأجبتــه لطلبــه وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/28‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33414189‬وتاريــخ ‪ 1433/06/21‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331156610‬وتاريــخ ‪ 1433/06/21‬ه ـ ففــي يــوم‬\n‫اإلثنــن املوافــق‪ 1434/03/02‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف بالقصيــم برقــم ‪3491001‬يف ‪1434/2/27‬هـ‬\n‫وبرفقهــا قــرار محكمــة االســتئناف بالقصيــم رقــم ‪ 3431184‬يف‬\n‫‪1434/2/5‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة لــم يظهــر مــا يوجــب املالحظــة علــى مــا حكــم‬\n\n\n                                                                                     ‫‪114‬‬\n\f      ‫بــه فضيلتــه وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه أجمعــن‬\n                                         ‫و للمعلوميــة حــرر يف ‪1433/3/2‬ه ـ ‪.‬‬\n\n\n\n\n‫‪115‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":110,"source_page_end":115,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cb2a026e909bbc4495aefdeec3b5465eedc16856a1c4f88eb1db59ab6c7058ee","normalized_text_hash":"3f9899f429ac87d77eae26be748d2ed33986664337ea9b17cae25d745461a569","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p110-33470421"},{"id":"7d5c01fc-b550-50e1-9ba6-30510b092863","document_type":"judgment","category":"judicial","subcategory":"general","title":"جرائم معلوماتية -نشر معلومات ووثائق رسمية سرية -إنشاء صفحة على موقع التواصل االجتماعي للتشهير -االتهام بالفساد اإلداري -التعرض ألشخاص وأعراضهم بالقدح والذم -نشر صور شخصية دون علم صاحبها -تصوير مستندات رسمية سرية ونشرها -حيازه تعاويذ وطالسم سحرية -حيازة صور تتضمن ايحاءات جنسية يف الهاتف اجلوال -ضبط واقعة من غير جهة مختصة -التعزير بأخذ التعهد .","document_number":"34206789","case_number":"33349247","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/06","year":"1434","subject":"جرائم معلوماتية -نشر معلومات ووثائق رسمية سرية -إنشاء صفحة على موقع التواصل االجتماعي للتشهير -االتهام بالفساد اإلداري -التعرض ألشخاص وأعراضهم بالقدح والذم -نشر صور شخصية دون علم صاحبها -تصوير مستندات رسمية سرية ونشرها -حيازه تعاويذ وطالسم سحرية -حيازة صور تتضمن ايحاءات جنسية يف الهاتف اجلوال -ضبط واقعة من غير جهة مختصة -التعزير بأخذ التعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34206789 :‬تاريخه‪1434/05/06 :‬هـ‬\n                    ‫رقم الدعوى ‪33349247 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34241045‬تاريخه ‪1434/06/14 :‬هـ‬\n\n\n ‫جرائــم معلوماتيــة ‪ -‬نشــر معلومــات ووثائــق رســمية ســرية ‪ -‬إنشــاء‬\n ‫صفحــة علــى موقــع التواصــل االجتماعــي للتشــهير ‪ -‬االتهــام بالفســاد‬\n ‫اإلداري ‪ -‬التعــرض ألشــخاص وأعراضهــم بالقــدح والــذم ‪ -‬نشــر‬\n ‫صــور شــخصية دون علــم صاحبهــا ‪ -‬تصويــر مســتندات رســمية ســرية‬\n ‫ونشــرها ‪ -‬حيــازه تعاويــذ وطالســم ســحرية ‪ -‬حيــازة صــور تتضمــن‬\n ‫ايحــاءات جنســية يف الهاتــف اجلــوال ‪ -‬ضبــط واقعــة مــن غيــر جهــة‬\n                                      ‫مختصــة ‪ -‬التعزيــر بأخــذ التعهــد ‪.‬‬\n\n\n\n\n                 ‫‪ -1‬املواد (‪ )49/34/33/31‬من نظام اإلجراءات اجلزائية ‪.‬‬\n                           ‫‪ -2‬املادة (‪ )190‬من نظام اإلجراءات اجلزائية ‪.‬‬\n  ‫‪ -3‬التعميم السامي البرقي رقم ‪/2312‬م ب وتاريخ ‪1426/02/17‬هـ‪.‬‬\n\n\n\n\n ‫توجيــه االتهــام للمدعــى عليهــا املوظفــة مبجمــع ‪ ..............‬للصحــة‬\n ‫النفســية بالدمــام بإنشــاء صفحــه علــى موقــع التواصــل االجتماعــي‬\n ‫الفيــس بــوك وجعلهــا منبــر ًا اعالمي ـ ًا للتشــهير بالعاملــن يف مجمــع‬\n ‫‪ ..............‬للصحــة النفســية بالدمــام واتهامهــم بالفســاد اإلداري‬\n ‫والتعــرض ألشــخاصهم وأعراضهــم بالقــدح والــذم ونشــر صورهــم‬\n\n                                                                               ‫‪116‬‬\n\f      ‫الشــخصية وتصويــر مســتندات رســمية ســرية ونشــرها وحيــازة تعاويــذ‬\n      ‫وطالســم ســحرية وصــورة واحــده تتضمــن إيحــاءات جنســية يف جهــاز‬\n      ‫هاتفهــا اجلــوال حيــث ورد بــاغ لشــرطة الدمــام مــن املشــرف العــام‬\n      ‫علــى مجمــع ‪ ..............‬للصحــة النفســية بالدمــام مضمونــه انــه مت نشــر‬\n      ‫معلومــات ووثائــق رســمية ســرية تتعلــق باملجمــع ومبرضــى املجمــع‬\n      ‫وانــه مت التشــهير بعــدد مــن موظفــي املجمــع باتهامهــم بالفســاد والتزويــر‬\n      ‫والســرقة وتعــدى األمــر إلــى أعــراض بعــض منســوبات املستشــفى وذلــك‬\n      ‫علــى موقــع الفيــس بــوك وعلــى شــبكة االنترنــت ‪ -‬طلــب املدعــي العــام‬\n      ‫إثبــات مــا أســند للمدعــى عليهــا واحلكــم عليهــا بالعقوبــة الــوارده يف‬\n      ‫الفقــرة (‪ )5‬مــن املــادة الثالثــة مــن نظــام مكافحــة اجلرائــم املعلوماتيــة‬\n      ‫لتشــهرها باآلخريــن وإحلــاق الضــرر بهــم عبــر وســائل االنترنــت والفقــرة‬\n      ‫(‪ )1‬مــن املــادة السادســة مــن نظــام مكافحــة جرائــم املعلوماتية الحتواء‬\n      ‫جهازهــا اجلــوال علــى صــور حتتــوي على مايخالف القيــم الدينية واآلداب‬\n      ‫العامــة واملــادة (‪ )13‬مــن نظــام مكافحــة اجلرائــم املعلوماتيــة ومصــادرة‬\n      ‫جهــاز اجلــوال املســتخدم يف اجلرميــة واحلكــم عليهــا بعقوبــة تعزيريــة‬\n      ‫تزجرهــا وتــردع غيرهــا ‪ -‬أنكــرت املدعــى عليهــا مــا نســب إليهــا‬\n      ‫وأقــرت بتصويــر مالحظــة متريضيــة مــن ملــف إحــدى املريضــات وهــي‬\n      ‫ورقــة واحــدة لــم يذكــر فيهــا اســم املريضــة وال رقــم ملفهــا والغــرض‬\n      ‫مــن التصويــر هــو االســتفادة منهــا يف مجــال العمــل ‪ -‬جــرى االطــاع‬\n      ‫علــى محضــر االســتجواب والقبــض والتفتيــش وخطــاب املشــرف العــام‬\n      ‫علــى مجمــع ‪ ..............‬للصحــة النفســية املوجــه ملديــر شــرطة الدمــام‬\n      ‫‪ -‬ذكــرت املدعــى عليهــا بــان جوالهــا أخــذ منهــا بالقــوة ومكــث‬\n      ‫لــدى إدارة املجمــع عــدة ايــام قبــل إحالتــه للشــرطة ‪ -‬طلــب القاضــي‬\n\n\n‫‪117‬‬\n\f‫مــن املدعــي العــام الشــهود فلــم يحضرهــم ‪ -‬جــرى رصــد املكاتبــات‬\n‫الرســمية الدائــرة بشــأن الدعــوى ‪ -‬حيــث إن مــن قــام بالضبــط جهــه‬\n‫إداريــة وليســت جنائيــة فهــو مخالــف للمــواد (‪31‬و‪33‬و‪34‬و‪ )49‬مــن نظــام‬\n‫ا بنــاء علــى املــادة (‪)140‬‬‫اإلجــراءات اجلزائيــة وعليــه فيعــد إجــراء ًا باطـ ً‬\n‫مــن نفــس النظــام‪ -‬صــدر احلكــم بــرد دعــوى املدعــي العــام لعــدم ثبوتهــا‬\n‫وثبــوت إدانــه املدعــى عليهــا بتصويــر ورقــة مــن ملــف إحــدى املريضــات‬\n‫دون مبــرر مقبــول ومعاقبتهــا علــى ذلــك بأخــذ تعهــد عليهــا بعــدم العــودة‬\n                ‫ملــا بــدر منهــا ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n‫برقــم ‪ ................‬وتاريــخ ‪1433/ 5 / 19‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ ..............‬وتاريــخ ‪1433/ 5 / 19‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪/‬‬\n‫حاملــة الســجل املدنــي رقــم (‪ )...............‬ففــي يــوم‬                ‫ضــد ‪/‬‬\n‫األحــد ‪1433/ 6 / 15‬ه ـ فتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر‬\n‫املدعــي العــام واملدعــى عليهــا املدونــة هويتهــا بعاليــه واملعــرف بهــا مــن‬\n‫قبــل زوجهــا حامــل الســجل املدنــي رقــم ‪ ................‬وقــدم املدعــي العــام‬\n‫الئحــة الدعــوى املتضمنــة مــا يلــي ‪ ( :‬بصفتــي مدعي ـ ًا عامــا يف دائــرة‬\n‫التحقيــق واإلدعــاء العــام مبحافظــة القطيــف أدعــي علــى‪،............... :‬‬\n‫البالغــة مــن العمــر (‪ )..‬عامـ ًا ‪ ،‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ ، )...................‬محصنــة ‪ ،‬موظفــة حكوميــة‪ ،‬مفــرج عنهــا‬\n‫اســتناد ًا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬وتقيــم مبحافظة‬\n\n                                                                                       ‫‪118‬‬\n\f      ‫القطيــف‪ .‬ورد بــاغ لشــرطة الدمــام مــن املشــرف العــام علــى مجمــع‬\n      ‫‪ ..............‬للصحــة النفســية بالدمــام مضمونــه أنــه مت نشــر معلومــات‬\n      ‫ووثائــق رســمية ســرية تتعلــق باملجمــع ومبرضــى املجمــع وأنــه مت التشــهير‬\n      ‫بعــدد مــن موظفــي املجمــع باتهامهــم بالفســاد والتزويــر والســرقة وتعــدى‬\n      ‫األمــر إلــى أعــراض بعــض منســوبات املستشــفى وذلــك علــى موقــع‬\n      ‫الفيســبوك علــى شــبكة االنترنــت‪ ،‬وأن إدارة املستشــفى قــد عملــت‬\n      ‫علــى تشــكيل فريــق عمــل للتأكــد مــن ســامة اإلجــراءات ومنهــا منــع‬\n      ‫اســتخدام أجهــزة التصويــر املدمجــة باجلــوال داخــل أجنحــة تنــومي النســاء‬\n      ‫‪ ،‬مرفقــا بــه محضــر إثبــات تضمــن أنــه بتاريــخ ‪1433/11/27‬ه ـ وأثنــاء‬\n      ‫إحــدى جــوالت املتابعــة املســائية تبــن قيــام املدعــى عليهــا بطلــب ملــف‬\n      ‫مريضــة يحتــوي علــى معلومــات ســرية بــدون مبــرر مهنــي أو عالجــي‬\n      ‫رغــم أن ملــف املريضــة مغلــق وقــد خرجــت مــن املجمــع منــذ أحــد عشــر‬\n      ‫شــهرا ‪ ،‬عندهــا مت توجيــه مشــرفة التمريــض وموظفــة األمــن بالدخــول‬\n      ‫لقســم النســاء ملعرفــة ســبب طلــب امللــف والتأكــد مــن عــدم تصويــره‬\n      ‫وقــد تبــن لهــن أن املدعــى عليهــا قــد تركــت موقــع عملهــا واجتمعــت مــع‬\n      ‫بعــض املوظفــات بغرفــة الصيدليــة الداخليــة ومعهــن ملــف املريضــه وقــد‬\n      ‫تبــن أن املدعــى عليهــا حتمــل جــوال مــزود بكاميــرا ومت ضبطــه مــن‬\n      ‫قبــل الفريــق املكلــف باملتابعــة‪ ،‬وبتشــكيل جلنــة داخليــه للتحقيــق يف‬\n      ‫األمــر تبــن لهــم احتــواء اجلــوال علــى صــورة مــن تلــك الصــور التــي نشــرت‬\n      ‫علــى االنترنــت وصــورة مــن صفحــة مــن ملــف املريضــة‪ .‬وباالطــاع‬\n      ‫مــن قبــل محقــق القضيــة علــى محتويــات جــوال املدعــى عليهــا وهــو‬\n      ‫مــن نــوع سامســوجن تبــن احتوائــه علــى التالــي‪-1 :‬عــدد مــن الصــور‬\n      ‫امللتقطــة تظهــر فيهــا صــور ألوراق لونهــا أبيــض حتتــوي علــى معلومــات‬\n\n\n‫‪119‬‬\n\f‫عــن مريضــه‪ ،‬ويتضــح مــن قراءتهــا أنهــا إحــدى نزيــات املجمــع الــذي‬\n‫تعمــل فيــه املدعــى عليهــا ومكتــوب فيهــا وصــف حلالــه تعرضــت لهــا‬\n‫املريضــة وهــي محاولتهــا االنتحــار‪ ،‬وقــد أتضــح أن تاريــخ التقاطهــا هــو‬\n‫‪2011/10/25‬م الســاعة ‪ 8.16‬مســاء والــذي يوافــق ‪1432/11/27‬هــ‪،‬‬\n‫وقــد تبــن أيضــا مــن خــال الرجــوع ألوراق القضيــة أنــه تاريــخ وقــوع‬\n‫احلادثــة يف املجمــع وقــد ورد يف االســتدعاء املقــدم مــن املدعــى عليهــا‬\n‫أنــه يف يــوم ‪1432/11/27‬ه ـ الســاعة التاســعة حصلــت احلادثــه‪-2 .‬عــدد‬\n‫مــن الصــور حتتــوي علــى تعويــذات وأدعيــة شــركية‪-3 .‬صــوره حتتــوي‬\n‫علــى رســم يحتــوي علــى إيحــاءات جنســية‪ .‬وباإلطــاع علــى تقريــر األدلــة‬\n‫اجلنائيــة رقــم (‪/87‬وســائط‪1432/‬هـ) واملرفــق معــه عــدد (‪ )126‬صــورة‬\n‫منســوخة مــن ســي دي للصفحــة املنشــورة علــى موقــع الفيســبوك علــى‬\n‫االنترنــت تبــن احتــواء الصــور علــى صــور شــخصية ألشــخاص وعبــارات‬\n‫مدونــة حتــت أســمائهم وصــور لوثائــق ومخاطبــات جميعهــا تتعلــق‬\n‫باملجمــع ويظهــر مــن شــكلها اخلارجــي أنهــا صــورت بكاميــرا تصويــر‬\n‫فوتوغرافيــه وليســت كاميــرا تصويــر ورقيــه ‪،‬كمــا يظهــر فيها صور‬\n‫شــخصية لعــدد مــن موظفــي املجمــع بعضهــا يتضــح مــن االطــاع عليهــا‬\n‫أنهــا أخــذت خلســة ‪ ،‬ودونــت حتتهــا عبــارات تتضمــن الســب والتشــهير‬\n‫واالتهــام بالفســاد اإلداري كمــا تتضمــن إحــدى العبــارات التعــرض‬\n‫لعــرض إحــدى العامــات باملجمــع بالتلميــح بفســادها األخالقــي‪ .‬وقــد‬\n‫قامــت املدعــى عليهــا بعــد ضبطهــا مــن قبــل جهــة عملهــا وفــق مــا ورد يف‬\n‫احملضــر املشــار إليــه بالتقــدم ببــاغ ملركــز شــرطة الدمــام مضمونــه‬\n‫أنهــا قــد تعرضــت لالعتــداء اجلســدي أثنــاء ضبطهــا يف محاولــة منهــا‬\n‫لاللتفــاف علــى جهــة عملهــا وللضغــط عليهــم بهــذه الدعــوى وقــد تبــن‬\n\n\n                                                                                   ‫‪120‬‬\n\f      ‫عــدم وجــود أدلــة كافيــه تثبتهــا‪ .‬وباســتجواب املدعى عليها نفت نشــرها‬\n      ‫ألي مســتندات علــى شــبكة االنترنــت وأقــرت بتصويرهــا مللــف إحــدى‬\n      ‫املريضــات بجوالهــا وبــررت ذلــك بأنهــا كانــت تقصــد منــه االسترشــاد‬\n      ‫به يف عملها كونه مســجل عليه مالحظات متريضية وأرادت االســتفادة‬\n      ‫منــه‪ .‬وقــد انتهــى التحقيــق معهــا إلــى توجيــه االتهــام إليهــا بإنشــاء صفحــة‬\n      ‫علــى موقــع التواصــل االجتماعــي الفيســبوك وجعلهــا منبــر ًا إعالمي ـ ًا‬\n      ‫للتشــهير بالعاملــن يف مجمــع ‪ ..............‬للصحــة النفســية ‪..............‬‬\n      ‫واتهامهــم بالفســاد اإلداري والتعــرض ألشــخاصهم وأعراضهــم بالقــدح‬\n      ‫والــذم ونشــر صورهــم الشــخصية و تصويــر مســتندات رســميه ســرية‬\n      ‫ونشــرها‪ ،‬وحيــازة تعاويــذ وطالســم ســحريه و صــوره واحــده تتضمــن‬\n      ‫إيحــاءات جنســية يف جهــاز هاتفهــا اجلــوال‪ ،‬وذلــك لألدلــة والقرائــن‬\n      ‫التاليــة‪-1 :‬إقرارهــا بتصويرهــا مللــف إحــدى املريضــات بجهــاز هاتفهــا‬\n      ‫اجلــوال واملنــوه عنــه واملــدون يف محضــر االســتجواب املرفــق علــى اللفــة‬\n      ‫رقم(‪-2.)70/69‬إطالعهــا علــى ملــف املريضــة دون موافقــة رســمية‬\n      ‫ويف وقــت غيــر مناســب واالنتقــال بــه الــى مــكان منــزوي ثــم الشــروع‬\n      ‫يف تصويــره قرينــة علــى أن القصــد مــن تصويــره ســيء ولعمــل غيــر‬\n      ‫مشــروع‪-3 .‬تصويرهــا مللــف املريضــة مســتخدمة جهــاز هاتفهــا اجلــوال‬\n      ‫وعــدم تصويــره بالــة التصويــر الورقيــة قرينــة علــى أنهــا تنــوي نقلــه عبــر‬\n      ‫االنترنــت إلــى موقــع الفيســبوك‪-4.‬وجود تشــابه بــن املســتند املصــور‬\n      ‫يف جــوال املدعــى عليهــا واملســتندات املنشــورة ووســيلة التصويــر قرينــة‬\n      ‫علــى صحــة االتهام‪-5.‬مــا تضمنــه احملضــر املنــوه عنــه واملرفــق علــى‬\n      ‫اللفــة رقم(‪-6.)4-2‬مــا تضمنــه خطــاب املجمــع املشــار إليــه واملرفــق علــى‬\n      ‫اللفــات رقــم (‪-7.)9-7‬كــذب املدعــى عليهــا ونفيها احتــواء جوالها على‬\n\n\n‫‪121‬‬\n\f‫أي شــيء ثــم أقرارهــا الحقــا باحتوائــه علــى صــور مللف إحــدى املريضات‬\n‫دليــل علــى صحــة االتهام‪-8.‬قيــام املدعــى عليهــا مبحاولــة االلتفــاف علــى‬\n‫جرميتهــا بالتقــدم بدعــوى تعرضهــا لالعتــداء اجلســدي قرينــة علــى صحــة‬\n‫االتهــام‪ .‬وبالبحــث عمــا إذا كان لهــا ســوابق لــم يعثــر لهــا علــى ســوابق‬\n‫جنائيــة‪ .‬وحيــث أن مــا أقدمــت عليــه املذكــورة ‪ -‬وهــي بكامــل أهليتهــا‬\n‫املعتبــرة شــرعا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرعا لــذا أطلــب إثبــات‬\n‫مــا اســند إليهــا شــرعا واحلكــم عليهــا بالعقوبــة الــواردة يف الفقــرة (‪)5‬‬\n‫مــن املــادة الثالثــة مــن نظـ ــام مكافحــة جرائــم املعلوماتيــة لتشــهيرها‬\n‫باآلخريــن وإحلــاق الضــرر بهــم عبــر وســائل اإلنترنــت ‪ ،‬والفقــرة (‪)1‬‬\n‫مــن املــادة السادســة مــن نظـ ــام مكافحــة جرائــم املعلوماتيــة الحتــواء‬\n‫جهازهــا اجلــوال علــى صــور حتتــوي علــى مــا يخالــف القيــم الدينيــة‬\n‫واآلداب العامــة ‪ ،‬و املــادة (‪ )13‬مــن نظـ ــام مكافحــة جرائــم املعلوماتيــة‬\n‫الصــادر باملرســوم امللكــي رقــم (م‪ )17 /‬وتاريــخ ‪1428 /3 /8‬ه ـ‬\n‫ملصــادرة جهــاز اجلــوال املســتخدم يف اجلرميــة‪ ،‬واحلكــم عليهــا بعقوبــة‬\n‫تعزيريــه تزجرهــا وتــردع غيرهــا ‪ ).‬ا‪ .‬ه ـ وبعــرض الدعــوى علــى املدعــى‬\n‫عليهــا أجابــت بقولهــا مــا جــاء يف الدعــوى كلــه غيــر صحيــح ســوى أنــي‬\n‫أقــر بتصويــر مالحظــة متريضيــة مــن ملــف إحــدى املريضــات وهــي ورقــة‬\n‫واحــدة وليــس مذكــورا فيهــا اســم املريضــة وال رقــم ملفهــا الطبــي وقــد‬\n‫صورتهــا بغــرض االســتفادة منهــا يف مجــال عملــي هــذا جوابــي وبعــرض‬\n‫ذلــك علــى املدعــي العــام قــال الصحيــح مــا جــاء يف دعــواي وبســؤاله‬\n‫البينــة قــال بينتــي ذكرتهــا يف الدعــوى وأطلــب رصدهــا هــذا جوابــي‬\n‫وبنــاء عليــه فقــد جــرى رفــع اجللســة لرصــد البينــات ويف جلســة أخــرى‬\n‫حضــر املدعــي العــام واملدعــى عليهــا واملعــرف بهــا وأبــرزت املدعــى‬\n\n\n                                                                                   ‫‪122‬‬\n\f      ‫عليهــا مذكــرة مكونــة مــن أربــع ورقــات وقالــت هــذا جــواب مفصــل‬\n      ‫عــن الدعــوى وتفنيــد لألدلــة وأطلــب االطــاع عليهــا وضمهــا للمعاملــة‬\n      ‫هــذا مــا لــدي فاطلعــت عليهــا وأمــرت بضمهــا للمعاملــة وباالطــاع علــى‬\n      ‫أدلــة املدعــي العــام وجــدت علــى اللفــات رقــم ‪ 70-69‬اســتجوابا للمدعــى‬\n      ‫عليهــا يتضمــن مــا نصــه‪ ( :‬س ‪ .‬أنــت متهمــة بالتشــكيك أو الطعــن يف‬\n      ‫نزاهــة املوظــف العــام ؟ ج ‪ .‬غيــر صحيــح ‪ .‬س ‪ .‬باالطــاع علــى جهــاز‬\n      ‫اجلــوال الــذي وجــد معــك أثنــاء قيامــك بتصويــر مســتندات يف املستشــفى‬\n      ‫وجــد بــه التالــي ‪ :‬صــور ملســتند رســمي يبــدو منــه أنــه ملــف مريضــة‬\n      ‫كانــت حتــاول االنتحــار فمــا قصــدك مــن تصويــره ؟ ج ‪ .‬صورتــه لغــرض‬\n      ‫حفــظ مالحظــة متريضيــة فقــط ولالســتفادة منهــا يف مجــال عملــي ولــم‬\n      ‫أصــور اســم املريضــة أو رقــم ملفهــا حفاظ ـ ًا علــى ســرية املعلومــات ‪ .‬س‬\n      ‫‪ .‬باالطــاع علــى محتويــات جهــاز اجلــوال وجــد بــه صــور ألوراق حتتــوي‬\n                                                 ‫علــى طالســم ســحرية فمــا قولــك ؟‬\n      ‫ج ‪ .‬ال أعلم عنها ‪ .‬س ‪ .‬كذلك وجد صور حتتوي على إيحاءات جنسية‬\n      ‫فمــا قولــك ؟ ج ‪ .‬ال أعلــم عنهــا شــيئا ‪ ).‬ا‪.‬ه ـ كمــا وجــدت علــى اللفــات‬\n      ‫‪ 2‬و ‪ 3‬و ‪ 4‬صــورة محضــر يتضمــن مــا نصــه ‪ ( :‬يف يــوم الثالثــاء املوافــق‬\n      ‫‪1432/11/27‬ه ـ تلقيــت أنــا ‪ .............. /‬مشــرفة قســم النفســية نســاء‬\n      ‫اتصــا ًال هاتفيـ ًا مــن قبــل مديــر خدمــات التمريــض ‪ /‬يف متــام الســاعة ‪30‬‬\n      ‫‪ 7 :‬مســاء ًا إلبالغــي بــأن املشــرف العــام علــى املجمــع كلفنــا بعمــل جولــة‬\n      ‫تفقديــة علــى األقســام ونظــر ًا لعــدم مقدرتهــم علــى دخــول القســم إال‬\n      ‫يف وجــود مشــرفة القســم أو مــن ينــوب عنهــا قــام بإبالغــي للقــدوم إلــى‬\n      ‫املجمــع لعمــل اجلولــة بســحب جــواالت الكاميــرا إن وجــدت مــع أحــد مــن‬\n      ‫الزميــات وتفقــد أحــوال القســم وبالفعــل مت تنفيــذ التعليمــات وتوجهــت‬\n\n\n‫‪123‬‬\n\f‫إلــى املجمــع ووصلــت يف متــام الســاعة ‪ 08 : 5‬مســاء ًا وعنــد طــوارئ‬\n‫النفســية وجــدت املديــر املنــاوب ‪ /‬يف انتظــاري إلبالغــي بــأن املمرضــة‬\n‫قامــت بســحب ملــف مريضــة مــن الســجالت الطبيــة ممــا يقــارب مــن‬\n‫النصــف ســاعة ومــازال امللــف حتــى اآلن بحوزتهــا داخــل القســم فتلقيــت‬\n‫أوامــر مــن جلنــة املــرور التاليــة اســماؤهم (‪ ).............‬بدخــول القســم‬\n‫بصحبــة حارســة األمــن ‪ /‬لتجميــع املمرضــات يف محطــة التمريــض‬\n‫وســحب جــواالت الكاميــرا إن وجــدت معهــم وبالفعــل توجهــت إلــى‬\n‫القســم بصحبــة حارســة األمــن وعنــد دخولــي القســم لــم أجــد كل‬\n‫املمرضــات مبحطــة التمريــض وبســؤال رئيســة الشــفت أفــادت بــأن‬\n‫املمرضــات التاليــة اســماؤهم متواجــدات بالصيدليــة الداخليــة بالقســم‬\n‫(‪ ).................‬فتوجهــت إلــى الصيدليــة عبــر البــاب اخلارجــي فقابلتنــي‬\n‫املمرضــة وبــدا عليهــا عالمــات الدهشــة والقلــق وبعــد دخولــي إلــى‬\n‫الصيدليــة وجــدت املمرضــة حتمــل امللــف الــذي مت ســحبه مــن الســجالت‬\n‫الطبيــة كمــا أفــاد املديــر املنــاوب مفتــوح وتقــرأ فيــه وبجوارهــا املمرضة‬\n‫دون التقيــد بالــزي الرســمي للعمــل وكانــت ترتــدي غطــاء أســود قمــت‬\n‫بســحب امللــف مــن املمرضــة ‪ /‬وســألتها مــن ســحب امللــف مــن اخلــارج‬\n‫قالــت إحنــا ال املدعــى عليهــا هــي مــن ســحبته وبســؤال املدعــى عليهــا‬\n‫أفــادت بــأن عندمــا دخلــت ِكان امللــف مــع مــن ؟ ‪...../‬صــح ؟ بعدهــا‬\n‫مت إبالغهــم بوضــع غطــاء الوجــه لدخــول اللجنــة لعمــل جولــة تفقديــة‬\n‫علــى القســم وبالفعــل نفــذوا التعليمــات وتوجهــوا إلــى خــارج الصيدليــة‬\n‫إلــى محطــة التمريــض بعدهــا قــام أ‪.............../‬بــأن ســحب جــواالت‬\n‫الكاميــرا مــن الزميــات وبالفعــل مت ســؤال الزميــات بــأن مــن معهــا‬\n‫جــوال كاميــرا تقــوم بتســليمه فســلمت املمرضــة ‪............/‬جوالهــا أمــا‬\n\n\n                                                                                    ‫‪124‬‬\n\f      ‫املمرضــة ‪ /‬أفــادت بــأن جوالهــا ( كلمــة غيــر واضحــة بســبب التصويــر‬\n      ‫) حارســات األمــن خــارج القســم أمــا بقيــة الزميــات األجانــب ال يحملــن‬\n      ‫جــواالت كاميــرا وأمــا بالنســبة للممرضــة املدعــى عليهــا فاعترضــت‬\n      ‫ورفضــت أن تســلم جوالهــا وقالــت انــه ليــس مــن حــق أي أحــد ســحب‬\n      ‫جوالهــا منهــا وأن اجلــوال يحــوي أشــياء خاصــة ليــس مــن حــق أي فــرد‬\n      ‫االطــاع عليهــا فتــم إبالغهــا بأنــه لــم يقــم أحــد بالتعــرض إلــى اجلــوال‬\n      ‫أو تفقــده بــل هــو إجــراء ســحب فقــط فرفضــت بشــدة وقاومــت وقامــت‬\n      ‫بفتــح اجلــوال وهــو يف حوزتهــا ومحاولــة مســح صــور منــه عليــه قمــت أنــا‪/‬‬\n      ‫بوضــع يــدي علــى شاشــة اجلــوال ولكــن املمرضــة قاومــت وفـ ّـرت إلــى‬\n      ‫مــكان ضيــق بجــوار املغســلة املوجــودة بداخــل محطــة التمريــض والقيام‬\n      ‫مبســح صــور فقمــت بضــم املمرضــة مــن اخللــف ومحاولــة أخــذ اجلــوال و‬\n      ‫قمــت بوضــع يــدي اليمنــى علــى الشاشــة فقامــت املمرضــة برفــع يــدي‬\n      ‫والعــض علــى أصبــع يــدي األوســط ممــا أدى إلــى حــدوث ألــم ال يحتمــل‬\n      ‫بــه وبالفعــل قمــت بســحب اجلــوال بقــوة مــن يدهــا وقمــت بتســليمه إلــى‬\n      ‫املديــر املنــاوب وذلــك بعــد تلقــي أمــر منــه بســحبة مــن املمرضــة مهمــا‬\n      ‫قاومــت وبعدهــا (عبــارة غيــر واضحــة بســبب التصويــر) إحضــار‬\n      ‫املمرضــات الثالثــة إلــى مبنــى اإلدارة إلنهــاء بعــض اإلجــراءات فتوجهــت‬\n      ‫معــي املمرضــة بعــد رفــض شــديد يف بــادى االمــر ولكــن املمرضــة‬\n      ‫‪....‬رفضــت رفض ـ ًا شــديد ًا تنفيــذ التعليمــات وتلفظــت ببعــض األلفــاظ‬\n      ‫مثــل مــا أجــى معاكــم أنتــم كلكــم ظلمــه أنــا هاعرفكــم كيــف‬\n      ‫تقومــوا بســحب اجلــوال منــي واالطــاع عليهــا بعدهــا توجهــت إلــى مبنــى‬\n      ‫اإلدارة الســتكمال اإلجــراءات مــع أعضــاء اللجنــة هــذا للعلــم واإلحاطــة‬\n                                                   ‫واتخــاذ الــازم حيــال ذلــك) ا‪.‬ه ـ‬\n\n\n‫‪125‬‬\n\f‫كمــا وجــدت علــى اللفــات ‪ 9 - 7‬خطابــا موجهــا مــن املشــرف العــام‬\n‫علــى مجمــع ‪ ..............‬للصحــة النفســية إلــى مديــر شــرطة الدمــام برقــم‬\n‫‪ 43‬س ‪ 41/32/‬يف ‪1432/12/18‬ه ـ يتضمــن مــا نصــه ‪ ( :‬إشــارة إلــى‬\n‫خطابكــم رقــم ‪ 4463/4/5/21‬ش وتاريــخ ‪1432/12/6‬ه ـ املتضمــن‬\n‫شــكوى املوظفــة لدينــا ‪ /‬عليــه نفيدكــم بــأن املوظفــة املذكــورة رهــن‬\n‫التحقيــق معهــا بتاريــخ ‪1432/11/27‬ه ـ ورفضــت احلضــور واالمتثــال‬\n‫للتحقيــق بنــاء علــى عــدد مــن املخالفــات النظاميــة والقانونيــة وذلــك‬\n‫حيــث ورد يف موقــع التواصــل االجتماعــي الفيــس بــوك باإلنترنــت بعنوان‬\n‫(فضائــح ‪ )..............‬تشــمل نشــر بعــض الوثائــق الرســمية الســرية التــي‬\n‫تخــص املجمــع واملرضــى والتشــهير مبوظفــن حكوميــن واتهامهــم‬\n‫بالفســاد والتزويــر والســرقة بــل تعــدى ذلــك ألعــراض بعــض املوظفــات‬\n‫‪ .‬وبنــاء علــى مــا ســبق رفــع خطــاب ســري لســعادة مديــر عــام الشــؤون‬\n‫الصحيــة حــول مــا ورد باملوقــع املشــار إليــه وكان توجيهــه بالتأكيــد‬\n‫علــى احملافظــة علــى الوثائــق الرســمية يف ضــوء التعاميــم الــواردة بهــذا‬\n‫اخلصــوص وعليــه كلــف فريــق عمــل للتأكــد مــن ســامة اإلجــراءات‬\n‫وعــدم اســتخدام أجهــزة التصويــر املدمجــة باجلــوال داخــل أجنحــة تنــومي‬\n‫النســاء وأثنــاء أحــد جــوالت املتابعــة بالفتــرة املســائية تبــن قيــام املوظفــة‬\n‫بطلــب ملــف مريضــة يحتــوي علــى معلومــات ســرية بــدون مبــرر مهنــي‬\n‫أو عالجــي وأن امللــف مغلــق وخــروج املريضــة مــن املجمــع منــذ أحــد‬\n‫عشــر شــهرا وعليــه مت توجيــه مشــرفة التمريــض بالنيابــة وموظفــة األمــن‬\n‫للدخــول لقســم تنــومي النســاء ملعرفــة ســبب طلــب امللــف والتأكــد مــن‬\n‫عــدم تصويــره وقــد وجــدن أن ‪ -1 :‬املوظفــات تركــن موقــع عملهــن‬\n‫مبحطــة التمريــض ووجدنهــن بغرفــة الصيدليــة الداخليــة للتعامــل مــع‬\n\n\n                                                                                         ‫‪126‬‬\n\f      ‫امللــف بشــكل ســري وغيــر نظامــي والقيــام بتصويــر امللــف بجــوال مــزود‬\n          ‫بكاميــرا (محــرز لــدى اإلدارة) وهــذه يف حــد ذاتهــا جرميــة قانونيــة ‪.‬‬\n      ‫‪ -2‬حمــل املوظفة‪......../‬واملوظفة‪.........‬جــوال مدمــج بكاميــرا داخــل‬\n      ‫األقســام النســائية الداخليــة وهــذه مخالفــة حســب التعاميــم الــواردة مــن‬\n                                                               ‫الــوزارة مرفــق صــورة ‪.‬‬\n      ‫‪ -3‬إصــرار غريــب مــن املوظفــة بعــدم تســليم اجلــوال طواعيــة للجنــة‬\n      ‫املكونــة مــن مشــرفة التمريــض واملشــرفة املناوبــة وحارســة األمــن ممــا‬\n      ‫زاد شــكوك اللجنــة التــي طلبــت اســتدعاء اإلدارة املناوبــة وكان لزامـ ًا‬\n      ‫علــى اللجنــة وحرصهــا بعــدم إفشــاء ســرية املرضــى أو ابتزازهــم وجــب‬\n      ‫التدخــل وحتريــز اجلــوال ‪ -4 .‬مقاومــة مشــرفة التمريــض عندمــا حاولــت‬\n      ‫أخــذ اجلــوال وهــي حتــاول مســح بيانــات وصــور قــد متــت علــى اجلــوال ممــا‬\n      ‫أدى إلــى اعتدائهــا علــى أعضــاء اللجنــة املشــار إليهــا وتهديدهــم‬\n      ‫بالشــكوى وعــض إصبــع مشــرفة التمريــض كمــا هــو وارد يف التقريــر‬\n      ‫املرفــق ‪ -5 .‬مت تشــكيل جلنــة برئاســة نائــب مديــر املستشــفى واألعضــاء‬\n      ‫املبينــن يف تقريــر التحقيــق املرفــق كمــا مت اســتدعاء أوليــاء أمــور‬\n      ‫املوظفــات املشــار إليهــن وقــد حضــر كل من ولي أمــر املمرضة (زوجها)‬\n      ‫وولــي أمــر املوظفــة (والدهــا) ولــم يحضــر ولــي أمــر املوظفــة وأثنــاء‬\n      ‫التحقيــق ادعــت املوظفــة بأنــه مت ضربهــا ولكــن لــم يظهــر للجنــة‬\n      ‫التحقيــق حينهــا أي أعــراض تشــير إلــى وجــود مــا تدعيــه بــل العكــس‬\n      ‫كان يــد مشــرفة التمريــض يظهــر عليهــا أعــراض العــض مرفــق تقريــر‬\n      ‫بالواقعــة ‪ .‬اســتمر التحقيــق حتــى الثانيــة صباحـ ًا ورفعــت اجللســة لتأخــر‬\n      ‫الوقــت واســتكمال التحقيــق ‪ .‬باليــوم التالــي مت تكويــن جلنــة نســائية‬\n      ‫لفتــح اجلــوال بحضــور زوج املوظفــة أثنــاء التحقيــق للتأكــد مــن خلــوه مــن‬\n\n\n‫‪127‬‬\n\f‫صــور للمرضــى أو وثائــق تخــص املستشــفى ومشــاهدة محتــواه وجــد‬\n‫اآلتــي ‪ -1 :‬تصويــر صفحــة ســرية مــن امللــف بعدمــا نزعتهــا مــن امللــف‬\n‫ومــن ثــم إعادتهــا بشــكل عشــوائي‪ -2 .‬وجــود صــورة مــن تلــك الصــور‬\n‫التــي نشــرت علــى موقــع الفيــس بــوك ‪ -3 .‬إفــادة املوظفــة بأنــه لــم يكــن‬\n‫ذلــك أول مــرة يطلــب امللــف بــل ســبق وطلــب مــن نفــس املوظفــات وبنفــس‬\n‫الطريقــة ‪ .‬علمـ ًا أنــه لــم حتضــر أي مــن املوظفــات حتــى تاريخــه إلكمــال‬\n‫التحقيــق بادعــاء املــرض ومــن ثــم رفــض التحقيــق ‪ .‬لــذا نأمــل إحالــة‬\n‫اجلــوال مــن قبلكــم إلــى جهــة االختصــاص التقنيــة وفحــص اجلــوال تقنيـ ًا‬\n‫وإعــادة مــا مت حذفــه وموافاتنــا مبحتــواه ومــا يتــم مــن اجــراءات أو‬\n‫عقوبــات ‪ .‬ميكــن تســليم اجلــوال احملــرز لــدى اإلدارة ومحضــر التحقيــق‬\n‫مــن خــال منــدوب رســمي مــن طرفكــم أو طــرف املجمــع حــن طلبــه‪.‬‬\n‫لــذا نأمــل أن يتــم إحالــة املعاملــة كاملــة جلهــة االختصــاص للتحقيــق‬\n‫فيمــا يخــص اجلرائــم اإللكترونيــة اخلاصــة باملوقــع املذكــور وجرائــم‬\n‫نشــر الوثائــق واملعلومــات الســرية وإفشــائها اخلــاص بتصوير وثائق ســرية‬\n‫متــس املرضــى إن كان للموظفــات عالقــة بذلــك ‪ .‬أمــا بالنســبة ملــا‬\n‫تقدمــت بــه املذكــورة مــن شــكوى مــا هــي إال محاولــة يائســة إلخفــاء‬\n‫تلــك املخالفــات اجلســيمة التــي ارتكبــت كمــا لــم تالحــظ اللجنــة أثنــاء‬\n‫التحقيــق التــي باشــرت الواقعــة حينهــا أي أعــراض بدليــل انهــا اســتمرت‬\n‫مــع زوجهــا يف التحقيــق بحضــور عــدد مــن األطبــاء داخــل املستشــفى‬\n‫حتــى الســاعة الثانيــة صباحـ ًا ســاعة رفــع وتأجيــل التحقيــق لليــوم التالــي‬\n‫) ا‪.‬ه ـ وبعــرض األدلــة علــى املدعــى عليهــا قالــت مــا ورد يف إجاباتــي جلهــة‬\n‫التحقيــق كلهــا صحيحــة ومــا عــداه فكلــه غيــر صحيــح وحقيقــة مــا‬\n‫حصــل أنــي كنــت يف الصيدليــة ومعــي ملــف املريضــة الــذي قمــت‬\n\n\n                                                                                      ‫‪128‬‬\n\f      ‫بتصويــر املالحظــة التمريضيــة منــه وكان معــي ممرضــة هنديــة‬\n      ‫وممرضــة اســمها فحضــرت لنــا مشــرفة التمريــض وطلبــت منــا وضــع‬\n      ‫غطــاء الوجــه واالجتــاه إلــى منطقــة التمريــض حلضــور بعــض املســؤولني‬\n      ‫وبالفعــل لبســنا احلجــاب وذهبنــا هنــاك فحضــر مديــر التمريــض ومعــه‬\n      ‫شــخصان ال أعرفهمــا وطلــب منــي أن أســلم جوالــي فرفضــت لوجــود‬\n      ‫صــور خاصــة فيــه فأصــر فرفضــت فقــال ملوظفــه اخــرى خذيــه منهــا‬\n      ‫بالقــوة فهجمــت علــي ووضعتنــي يف زاويــة ولفــت يــدي خلــف ظهــري‬\n      ‫وضغطــت بجســمها علــى كتفــي وظهــري ولــم تســتطع أخــذ اجلــوال‬\n      ‫فأزالــت غطــاء وجهــي فاضطــررت إلــى أن أصلــح غطــاء وجهــي فأخــذت‬\n      ‫اجلــوال منــي ولــم أقــم مبســح شــيء مــن اجلــوال ثــم منعونــي مــن اخلــروج مــن‬\n      ‫القســم حتــى حضــر زوجــي ثــم أمرونــا بالصعــود إلــى الــدور الثانــي وحقق‬\n      ‫معــي مجموعــة مــن الرجــال مــن ضمنهــم نائــب مديــر املستشــفى وطلبــوا‬\n      ‫االطــاع علــى اجلــوال فأفهمتهــم بأنــي امــرأة وأنــه يحتــوي صــورا خاصــة‬\n      ‫فســلموه حلارســتي أمــن لالطــاع علــى الصــور فقامتــا باالطــاع علــى‬\n      ‫الصــور ووجــدا صــورة املالحظــة التمريضيــة التــي صورتهــا هــذا جوابــي‬\n      ‫فســألتها هــل بينــك وبــن أو أحــد مــن طاقــم املستشــفى الــذي حقــق‬\n      ‫معــك تلــك الليلــة أي عــداوة ســابقة أو ســوء تفاهــم فأجابــت بقولهــا ال لــم‬\n      ‫يكــن هنــاك أي ســوء تفاهــم أو عــداوة ســابقة بينــي وبــن أحــد منهــم بــل‬\n      ‫كنــت أكــن التقديــر واالحتــرام للمشــرفة وكانــت متعاونــة معــي قبــل‬\n      ‫احلادثــة ولكــن أظــن أنهــم كانــوا مســتائني ممــا ينشــر يف الفيــس بــوك‬\n      ‫وجعلونــي كبــش فــداء هــذا جوابــي وبســؤال املدعــي العــام زيــادة بينــة‬\n      ‫وعــد بإحضارهــا ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى‬\n      ‫عليهــا واملعــرف بهــا ولــم يحضــر املدعــي بينتــه وطلــب مهلــة أخــرى‬\n\n\n‫‪129‬‬\n\f‫إلحضارهــا فأجبتــه لطلبــه وأفهمتــه بأنهــا املهلــة األخيــرة ثــم قالــت‬\n‫املدعــى عليهــا إنــي أطلــب الكتابة ملديرية الشــؤون الصحية لتزويدكم‬\n‫مبــا لديهــا مــن حتقيقــات وأفيدكــم بــأن أحــد موظفــي املستشــفى‬\n‫واســمه طلــب منــي ليلــة الواقعــة أن أكتــب ورقــة تتضمــن اعتــرايف بأنــي‬\n‫أسســت صفحــة الفيــس بــوك ثــم يســلمني جوالــي فرفضــت ذلــك كمــا‬\n‫أفيدكــم أنــي راجعــت مستشــفى صفــوى لعــاج مــا حلــق بــي مــن إصابات‬\n‫والتــي ال أزال يف مرحلــة العــاج الطبيعــي حتــى اآلن وأطلــب الكتابــة‬\n‫للمستشــفى إلفادتكــم بتقريــر طبــي بهــذا اخلصــوص هــذا مــا لــدي‬\n‫وبنــاء عليــه فقــد أجبــت املدعــى عليهــا لطلباتهــا ويف جلســة أخــرى حضــر‬\n‫املدعــي العــام واملدعــى عليهــا واملعــرف بهــا ولــم يحضــر الشــهود وكنــا‬\n‫قــد كتبنــا ملستشــفى صفــوى بكتابنــا رقــم ‪ 331327942‬يف‬\n‫‪1433/7/14‬ه ـ وللشــؤون الصحيــة باملنطقــة الشــرقية بكتابنــا رقــم‬\n‫‪ 331328038‬يف ‪1433/7/14‬ه ـ ولــم يردنــا جــواب علــى كتابينــا‬\n‫املذكوريــن ورفعــت اجللســة لرصــد اجلوابــن بعــد ورودهمــا ويف جلســة‬\n‫أخــرى حضــر املدعــي العــام واملدعــى عليهــا واملعــرف بهــا وقــد وردنــا‬\n‫كتــاب مديــر عــام الشــؤون الصحيــة باملنطقــة الشــرقية رقــم‬\n‫‪2/55956‬ع‪ 41/‬يف ‪1433/7/30‬ه ـ املتضمــن مــا نصــه ‪ ( :‬نفيــد‬\n‫فضيلتكــم بأنــه يوجــد لدينــا معاملــة تخــص مــا حــدث يــوم الثالثــاء‬\n‫‪1432/11/27‬ه ـ مســاء ًا بقســم نفســية نســاء مبجمــع ‪ ..............‬للصحــة‬\n‫النفســية بالدمــام واملمرضــة املذكــورة أعــاه هــي أحــد ذوي العالقــة‬\n‫مبــا حــدث وال يوجــد أي رابــط يف ذلــك مبــا ورد يف الدعــوى مــن‬\n‫تشــكيك وطعــن يف نزاهــة موظــف عــام ومــا حــدث كان قيــام جلنــة مــن‬\n‫املجمــع شــكلت بإشــراف وتوجيــه مــن نائــب املشــرف على املجمــع‪......./‬‬\n\n\n                                                                                  ‫‪130‬‬\n\f      ‫بعمليــة تفتيــش لقســم النفســية نســاء ثــم إجــراء حتقيــق مــع ثــاث‬\n      ‫ممرضــات ســعوديات مــن ضمنهــم املمرضــة املذكــورة وقــد مت التحفــظ‬\n      ‫علــى جوالهــا الشــخصي مــن قبلهــم بعــد تفتيشــه ‪ .‬أمــا فيمــا ورد مــن‬\n      ‫تصويــر مســتندات مــن ملفــات مرضــى مبجمــع ‪ ..............‬فإن املذكورة‬\n      ‫وحســب اعترافهــا الشــخصي قامــت فقــط بتصويــر مالحظــة متريضيــة‬\n      ‫مــن ملــف مريضــة لــم تكــن منومــه باملجمــع وهــي مــن قامــت بطلــب‬\n      ‫امللــف مــن قســم الســجالت الطبيــة وأن املالحظــة التمريضيــة ال تتضمــن‬\n      ‫رقــم امللــف او اســم املريضــة وهــو مــا أفــادت بــه يف محاضــر التحقيــق‬\n      ‫التــي أجريــت لهــا باملجمــع مــن قبــل اللجنــة‪ .‬علمـ ًا بأننــا لــم نقــم باســتالم‬\n      ‫جــوال املذكــورة مــن املجمــع ولــم نطلــع علــى محتوياتــه ومــا زال ملــف‬\n      ‫القضيــة مبكتبنــا ولــم يتــم اتخــاذ أي إجــراء حيالــه حتــى تاريخــه) ا‪.‬ه ـ‬\n      ‫وحيــث لــم يردنــا جــواب مستشــفى صفــوى فقــد قــررت رفــع اجللســة‬\n      ‫للتعقيــب عليــه ويف جلســة أخــرى حضــر ت املدعــى عليهــا واملعــرف بهــا‬\n      ‫وقــد وردنــا مــن مديــر مستشــفى صفــوى برقــم ‪ 41/25/56/80‬يف‬\n      ‫‪1433/8/6‬ه ـ تقريــر طبــي بشــأن املدعــى عليهــا يتضمــن مــا نصــه ‪( :‬‬\n      ‫العظــام ‪ :‬املذكــورة أعــاه راجعــت العيــادة يف يــوم ‪1432/12/2‬ه ـ‬\n      ‫بتحويــل مــن اإلســعاف وهــي تشــكو مــن ألــم شــديد بالكتــف األيســر‬\n      ‫إثــر التــواء للطــرف األيســر العلــوي قبــل ‪ 4‬أيــام وبالكشــف الطبــي تبــن‬\n      ‫وجــود ألــم شــديد وحتــدد يف حركــة الكتــف األيســر أعطيــت العــاج‬\n      ‫الــازم وأوصــي لهــا براحــة ملــدة ‪ 3‬أيــام ومراجعــة العيــادة ‪ .‬راجعــت‬\n      ‫املريضــة بتاريــخ ‪1432/12/6‬ه ـ مــع وجــود آالم مســتمرة وحركــة‬\n      ‫الكتــف مؤملــة ومحــدودة وأعطيــت العــاج الــازم وحتويــل إلــى العــاج‬\n      ‫الطبيعــي ومراجعــة العيــادة ‪ ،‬راجعــت املريضــة بتاريــخ ‪1432/12/24‬ه ـ‬\n\n\n‫‪131‬‬\n\f‫وأعطيــت العــاج الــازم وأوصــى لهــا براحــة ملــدة ‪ 4‬أيــام مــن تاريــخ‬\n‫‪1432/12/24‬ه ـ ‪ .‬العــاج الطبيعــي ‪ :‬تعانــي املريضــة مــن عــدم قدرتهــا‬\n‫علــى رفــع يدهــا يف كل االجتاهــات وألــم شــديد يف مفصــل الــذراع مــع‬\n‫الكتــف وأخــدت لدينــا حوالــي ‪ 9‬جلســات عــاج طبيعــي مبقــدار ‪3‬‬\n‫جلســات أســبوعيا مــدة شــهرين وذلــك لســوء حالتهــا ومتــت املراجعــات‬\n‫‪1433/1/1‬ه ـ‬             ‫‪1432/12/25‬ه ـ‬             ‫بتاريــخ ‪1432/12/23‬ه ـ‬\n‫‪1433/1/3‬ه ـ ‪1433/1/5‬ه ـ ‪1433/1/10‬ه ـ ‪1433/1/16‬ه ـ‬\n‫‪1433/1/18‬ه ـ ‪1433/2/1‬ه ـ ‪1433/2/2‬ه ـ ‪1433/2/14‬ه ـ‬\n‫‪1433/2/16‬ه ـ ‪1433/2/21‬ه ـ ‪1433/2/28‬ه ـ ‪1433/4/28‬ه ـ‬\n‫‪1433/5/19‬ه ـ ‪1433/5/25‬ه ـ ‪1433/6/4‬ه ـ وبعــد أخــد العــاج‬\n‫الطبيعــي زادت احلركــة مــن ‪ 180-0‬إلــى ‪ 180-110‬ولكنهــا مــا زالــت‬\n‫بحاجــة للعــاج مــن أجــل زيــادة احلركــة وزيــادة القــوى العضليــة للكتــف‬\n‫) ا‪.‬ه ـ وكانــت املدعيــة قــد تقدمــت باســتدعاء يف وقــت ســابق قيــد برقــم‬\n‫‪ 331539462‬يف ‪1433/8/14‬ه ـ ويتضمــن مــا نصــه ‪ ( :‬باإلشــارة إلــى‬\n‫اخلطــاب رقــم ‪/41‬ع‪ 55956/‬يف ‪1433/7/30‬ه ـ املوجــه مــن قبــل مديــر‬\n‫عــام الشــؤون الصحيــة لفضيلتكــم والــذي يبــن أنــه اعتــراف واضــح‬\n‫بأنــه مت أخــذ جوالــي مــن قبــل املستشــفى وبقــي يف حــوزة مــن اســتولى‬\n‫عليــه وأن املعلومــات التــي وردت املديريــة العامــة للشــؤون الصحيــة مــن‬\n‫قبــل املستشــفى تشــير فقــط للمالحظــة التمريضيــة فمــن أيــن جــاءت‬\n‫بقيــة األمــور مــا دام أنــه مت تفتيــش اجلــوال ‪ ،‬كل ذلــك يؤكــد بأنــه مت‬\n‫دس أشــياء يف جوالــي ) ا‪.‬ه ـ ويف جلســة أخــرى حضــرت املدعــى عليهــا‬\n‫واملعــرف بهــا وبتصفــح املعاملــة وجــدت علــى اللفــات ‪ 17-14‬قــرار اتهــام‬\n‫معــدا مــن محقــق القضيــة ‪ :‬ويتضمــن اطالعــه علــى جــوال املدعــى عليهــا‬\n\n\n                                                                                 ‫‪132‬‬\n\f      ‫املضبــوط وأنــه وجــد مــن محتوياتــه مــا يلــي ‪( :‬عــدد مــن الصــور حتتــوي‬\n      ‫علــى تعويــذات وأدعيــة شــركية و صــورة حتتــوي علــى رســم يحتــوي‬\n      ‫علــى إيحــاءات جنســية) ا‪ .‬ه ـ وبعرضــه علــى املدعــى عليهــا قالــت ‪ :‬لقــد‬\n      ‫ســحب جوالي مني يف املستشــفى بتاريخ ‪1432/11/27‬هـ عند الســاعة‬\n      ‫التاســعة مســاء تقريبــا بطريقــة غيــر رســمية وبقــي عنــد خصومــي حتــى‬\n      ‫‪1433/1/14‬ه ـ قبــل تســليمه جلهــة التحقيــق وبقــاء اجلــوال هــذه املــدة‬\n      ‫الطويلــة دليــل علــى أنــه مت تخزيــن مــا ضبــط فيــه مــن قبــل خصومــي وهــم‬\n      ‫‪ ........‬و‪ ............‬و‪ .............‬ومــن كان معهــم يف تلــك الليلــة مــن أنــاس ال‬\n      ‫أعرفهــم كمــا أنــه ُمــو ِرس معــي يف تلــك الليلــة ممارســات غيــر نظاميــة‬\n      ‫تتمثــل يف ســحب جوالــي بالقــوة ممــا أدى إلــى إصابتــي التــي ال أزال‬\n      ‫أتعالــج منهــا ثــم التحقيــق معــي مــن قبــل مجموعــة مــن األشــخاص يزيــد‬\n      ‫عددهــم علــى ثمانيــة أشــخاص يف آخــر الليــل مــن الســاعة الثانيــة عشــرة‬\n      ‫إلــى مــا بعــد الســاعة الواحــدة والنصــف ولــم يســمحوا لزوجــي باجللــوس‬\n      ‫بجــواري أثنــاء التحقيــق بــل جعلــوه يف مــكان بعيــد وأجلســوا بجــواري‬\n      ‫رجــا غيــر محــرم لــي وقــد ذكــرت يف املذكــرات التي ســبق أن قدمتها‬\n      ‫لكــم تفصيــا ملــا حصــل لــي يف املستشــفى تلــك الليلــة هــذا جوابــي‬\n      ‫وبنــاء عليــه فقــد قــررت الكتابــة للجهــة املختصــة لإلفــادة عــن الصــور‬\n      ‫املشــار إليهــا مــن قبــل محقــق القضيــة وعــن تاريــخ وســاعة تخزينهــا يف‬\n      ‫جــوال املدعــى عليهــا ويف جلســة أخــرى حضــرت املدعــى عليهــا واملعــرف‬\n      ‫بهــا وقــد جــرى يف وقــت ســابق مكاتبــة األدلــة اجلنائيــة بكتابنــا رقــم‬\n      ‫‪ 332146982‬يف ‪1433/12/19‬ه ـ ولــم يردنــا جــواب حتــى تاريخــه ويف‬\n      ‫جلســة أخــرى حضــرت املدعــي العــام واملدعــى عليهــا واملعــرف بهــا وقــد‬\n      ‫جرى يف وقت سابق مكاتبة األدلة اجلنائية بكتابنا رقم ‪332146982‬‬\n\n\n‫‪133‬‬\n\f‫يف ‪1433/12/19‬ه ـ ولــم يردنــا جــواب حتــى تاريخــه رغــم التعقيــب عليــه‬\n‫وبســؤال املدعــي العــام عــن مــدى حتقــق صفــة الضبــط اجلنائــي ملــن باشــر‬\n‫عمليــة ضبــط اجلــوال وهــل هــو مشــمول بالفقــرة رقــم (‪ )7‬مــن املــادة ‪26‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة قــال أطلــب مهلــة للتحقــق من ذلــك فأجبته‬\n‫لطلبــه ورفعــت اجللســة لذلــك وللتعقيــب علــى كتابنــا لألدلــة اجلنائيــة‬\n‫ويف جلســة أخــرى حضــر املدعــي العــام كمــا حضــرت املدعــى عليهــا‬\n‫واملعــرف بهــا وقــد وردنــا جوابــا علــى تعقيبنــا كتــاب مديــر شــرطة‬\n‫محافظــة القطيــف رقــم ‪ 1055/8/21‬يف ‪1434/3/28‬ه ـ املتضمــن مــا‬\n‫نصه ‪ ( :‬مت إحالة كامل املعاملة إلدارة شــؤون األمن بشــرطة محافظة‬\n‫القطيــف بكتابنــا رقــم ‪/604/8/12‬ت ش ق وتاريــخ ‪1434/2/16‬ه ـ )‬\n‫ا‪.‬ه ـ وأبــرز املدعــي العــام جوابــا مكتوبــا عمــا جــرى ســؤاله عنــه يف‬\n‫اجللســة املاضيــة ويتضمــن مــا نصــه ‪ ( :‬أفيــد فضيلتكــم أنــه مت تكليــف‬\n‫جلنــة مختصــة مــن قبــل إدارة املستشــفى وفقــا لتعميــم ‪-‬مرفــق نســخة منــه‬\n‫‪ -‬مديــر عــام الشــؤون الصحيــة باملنطقــة الشــرقية رقــم ‪41/3/14025‬‬\n‫يف ‪1426/3/22‬ه ـ واملبنــي علــى األمــر الســامي الكــرمي رقــم ‪/2312‬م‬\n‫ب يف ‪1426/2/17‬ه ـ واملتضمــن أن تقــوم اجلهــات احلكوميــة باتخــاذ‬\n‫اإلجــراءات املناســبة حلظــر اســتخدام أجهــزة الهاتــف اجلــوال واملــزودة‬\n‫بكاميــرا تصويــر يف األماكــن التــي تقتضــي املصلحــة أو الدواعــي‬\n‫األمنيــة أو الصحيــة حظــر اســتخدامه وحتيــل املخالــف إلــى اجلهــة‬\n‫املختصــة لتطبــق يف حقــه النصــوص النظاميــة ذات الصلــة وبعــد ضبــط‬\n‫املذكــورة وهاتفهــا النقــال مت إثبــات ذلــك مبحضــر ورفعــه جلهــة الضبــط‬\n‫املختصــة التخــاذ مــا يلــزم ) ا‪.‬ه ـ وباالطــاع علــى التعميــم املرفــق وجدتــه‬\n‫صــادرا مــن مديــر عــام الشــؤون الصحيــة باملنطقــة الشــرقية رقــم‬\n\n\n                                                                                     ‫‪134‬‬\n\f      ‫‪ 41/3/14025‬يف ‪1426/3/22‬هـ ويتضمن ما نصه ‪ ( :‬إحلاقا لتعميمنا‬\n      ‫رقــم ‪ 41/3/11797‬يف ‪1426/3/9‬ه ـ املبلــغ مبوجبــه األمــر الســامي‬\n      ‫الكــرمي رقــم ‪/2312‬م ب يف ‪1426/2/17‬ه ـ والــذي رأى أن تقــوم‬\n      ‫اجلهــات احلكوميــة باتخــاذ اإلجــراءات املناســبة حلظــر اســتخدام أجهــزة‬\n      ‫الهاتــف اجلــوال واملــزودة بكاميــرا تصويــر يف األماكــن التــي تقتضــي‬\n      ‫املصلحــة أو الدواعــي األمنيــة أو الصحيــة حظــر اســتخدامه وحتيــل‬\n      ‫املخالــف إلــى اجلهــة املختصــة لتطبــق يف حقــه النصــوص النظاميــة ذات‬\n      ‫الصلــة ) ا‪.‬ه ـ وبســؤال املدعــي العــام عــن نــص األمــر امللكــي املشــار إليــه‬\n      ‫قــال أطلــب مهلــة للكتابــة للجهــة املختصــة لتزويدنــا بصــورة منــه هــذا‬\n      ‫جوابــي فأجبتــه لطلبــه وبعــرض مــا ضبــط علــى املدعــى عليهــا قالــت ‪:‬‬\n      ‫الذيــن قامــوا بالضبــط ليســوا مخولــن بالضبــط مــن املديريــة العامــة‬\n      ‫للشــؤون الصحيــة ممــا يؤيــد مــا ذكرتــه مــن أن الضبــط غيــر مشــروع‬\n      ‫وكذلــك فــإن اجلــوال بقــي عنــد املستشــفى قرابــة شــهر ونصــف قبــل أن‬\n      ‫يقومــوا ببعثــه لهيئــة التحقيــق كمــا أنــي أمتســك بتعميــم ســمو ولــي العهد‬\n      ‫وزيــر الداخليــة رقــم ‪ 60603‬يف ‪1432/9/21‬ه ـ واملتضمــن أنــه يجــب‬\n      ‫مراعــاة التفريــق بــن أعمــال الضبــط اإلداري والضبــط اجلنائــي إضافــة‬\n      ‫إلــى أنــه ال يوجــد بــاغ مــن أحــد حتــى يقــوم هــؤالء بعمليــة الضبــط هــذا‬\n      ‫جوابــي ورفعــت اجللســة ملــا طلبــه املدعــي العــام وللتعقيــب علــى كتابنــا‬\n      ‫لــدى إدارة شــؤون األمــن بشــرطة محافظــة القطيــف ويف جلســة أخــرى‬\n      ‫حضــر املدعــي العــام كمــا حضــرت املدعــى عليهــا واملعــرف بهــا و‬\n      ‫باالطــاع علــى تعميــم وزارة العــدل رقــم ‪/13‬ت‪ 2598/‬يف ‪1426/2/30‬‬\n      ‫ه ـ وجدتــه يتضمــن مــا نصــه ‪ « :‬تلقينــا نســخة مــن التعميــم الســامي‬\n      ‫البرقــي برقــم ‪/2312‬م ب وتاريــخ ‪1426/2/17‬ه ـ ‪ ،‬ونصــه ‪ [ :‬اطلعنــا‬\n\n\n‫‪135‬‬\n\f‫علــى خطــاب معالــي األمــن العــام ملجلــس الــوزراء رقــم ‪ 3460‬وتاريــخ‬\n‫‪1425/11/23‬ه ـ ‪ ،‬املشــار فيــه إلــى أن مجلــس الــوزراء اطلــع خــال‬\n‫جلســته املنعقــدة بتاريــخ ‪1425/11/22‬ه ـ علــى املعاملــة املشــتملة علــى‬\n‫خطــاب صاحــب الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء‬\n‫ووزيــر الدفــاع والطيــران واملفتــش العــام رقــم ‪ 38103/2/2/2‬وتاريــخ‬\n‫‪1424/11/5‬ه ـ ‪ ،‬ومشــفوعه محضــر اللجنــة املشــكلة لدراســة‬\n‫اســتخدام الهاتــف اجلــوال يف الدوائــر احلكوميــة واألماكــن احلساســة ‪،‬‬\n‫وحتديــد العقوبــات التــي ســوف تطبــق علــى مخالفــي هــذه األنظمــة ‪،‬‬\n‫كمــا اطلــع علــى احملضــر رقــم ( ‪ ) 50‬وتاريــخ ‪1425/2/13‬ه ـ املعــد يف‬\n‫هيئــة اخلبــراء مبجلــس الــوزراء رقــم ‪ 2653‬وتاريــخ ‪1425/8/4‬ه ـ وعلــى‬\n‫برقيــة معالــي وزيــر االتصــاالت وتقنيــة املعلومــات رقــم ‪/188‬ب وتاريــخ‬\n‫‪1425/9/17‬ه ـ واملذكــرة اإليضاحيــة املرفقــة بهــا ‪ ،‬بشــأن اســتخدام‬\n‫الهاتــف اجلــوال يف الدوائــر احلكوميــة واألماكــن احلساســة ‪ ،‬والســماح‬\n‫ببيــع وتــداول جهــاز الهاتــف اجلــوال املــزود بكاميــرا تصويــر ‪ ،‬وعلــى‬\n‫األمــر الســامي رقــم ‪/1551/7‬م ب وتاريــخ ‪1425/10/29‬ه ـ القاضــي‬\n‫بالســماح باســتيراد وبيــع أجهــزة اجلــوال املــزودة بكاميــرا تصويــر رقميــة‬\n‫وتداولهــا يف الســوق احمللــي ‪ ،‬وعلــى توصيــة اللجنــة العامــة ملجلــس‬\n‫الــوزراء املتخــذة يف هــذا الشــأن ‪ ..‬ورأى مجلــس الــوزراء أن تقــوم اجلهــات‬\n‫احلكوميــة باتخــاذ اإلجــراءات املناســبة حلظــر اســتخدام أجهــزة الهاتــف‬\n‫اجلــوال يف األماكــن التــي تقتضــي املصلحــة أو الدواعــي األمنيــة أو‬\n‫الصحيــة حظــر اســتخدامه بهــا‪ ،‬وحتيــل املخالــف إلــى اجلهــة املختصــة‬\n‫لتطبــق يف حقــه النصــوص النظاميــة ذات الصلــة ‪ .‬ونرغــب إليكــم إنفــاذ‬\n‫مــا رآه مجلــس الــوزراء يف هــذا الصــدد ‪ ] ...‬أه ـ ل ــذا نرغــب إليكــم‬\n\n\n                                                                                   ‫‪136‬‬\n\f      ‫االطــاع واعتمــاد موجبــه فيمــا يخصكــم ) ا‪ .‬ه ـ فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وحيــث لــم يقــدم املدعــي العــام بينــة موصلــة‬\n      ‫بخصــوص صفحــة الفيــس بــوك وبنــاء علــى مــا أثبتــه محقــق القضيــة مــن‬\n      ‫وجــود عــدد مــن الصــور حتتــوي علــى تعويــذات وأدعيــة شــركية و صورة‬\n      ‫حتتــوي علــى رســم يحتــوي علــى إيحــاءات جنســية يف هاتــف املدعــى‬\n      ‫عليهــا وقــد دفعــت املدعــى عليهــا هــذا االتهــام بأنــه غيــر صحيــح وأنــه مت‬\n      ‫ســحب جوالهــا منهــا يف املستشــفى بتاريــخ ‪1432/11/27‬ه ـ عنــد‬\n      ‫الســاعة التاســعة مســاء تقريبــا بطريقــة غيــر رســمية وبقــي لــدى مــن قــام‬\n      ‫بضبطــه ‪-‬حســب ادعائها‪-‬حتــى ‪1433/1/14‬ه ـ ومجمــل إفادتهــا هــذه‬\n      ‫مؤيــد مبــا ورد يف كتــاب املشــرف العــام علــى مجمــع ‪ ..............‬للصحــة‬\n      ‫النفســية املوجــه إلــى مديــر شــرطة الدمــام برقــم ‪ 43‬س ‪ 41/32/‬يف‬\n      ‫‪1432/12/18‬ه ـ واحملضــر املعــد مــن مشــرفة قســم النفســية حيــث‬\n      ‫يتضمنــان بــأن الواقعــة حصلــت بتاريــخ ‪1432/11/27‬ه ـ وأنــه مت رفــع‬\n      ‫األوراق والهاتــف املضبــوط إلــى شــرطة الدمــام بتاريــخ ‪1432/12/18‬ه ـ‬\n      ‫وهــذا الفعــل ‪ -‬علــى فــرض أن مــن قامــوا بالضبــط مخولــن بذلــك ‪-‬‬\n      ‫مخالــف ملــا نصــت عليــه املــواد ‪ 31‬و ‪ 33‬و ‪ 34‬و ‪ 49‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة ‪ ،‬ويعــد هــذا اإلجــراء باطــا تأسيســا علــى املــادة ‪ 190‬مــن‬\n      ‫النظــام ذاتــه ‪ ،‬وبنــاء علــى إقــرار املدعــى عليهــا بتصويــر ورقــة مــن ملــف‬\n      ‫إحــدى املريضــات ال تشــتمل علــى اســم تلــك املريضــة وفعلهــا مخالــف ملــا‬\n      ‫ورد يف التعميم السامي البرقي رقم ‪/2312‬م ب وتاريخ ‪1426/2/17‬هـ‬\n      ‫ممــا يســتوجب معاقبتهــا العقوبــة املناســبة فقــد حكمــت مبــا يلــي ‪-1 :‬‬\n      ‫رد دعــوى املدعــي العــام بشــأن طلبه إثبات إدانــة املدعى عليها ومعاقبتها‬\n      ‫علــى إنشــاء صفحــة علــى موقــع التواصــل االجتماعــي الفيســبوك وجعلها‬\n\n\n‫‪137‬‬\n\f‫منبر ًا إعالمي ًا للتشــهير بالعاملني يف مجمع ‪ ..............‬للصحة النفســية‬\n‫بالدمــام واتهامهــم بالفســاد اإلداري والتعــرض ألشــخاصهم وأعراضهــم‬\n‫بالقــدح والــذم ونشــر صورهــم الشــخصية ‪ ،‬وحيــازة تعاويــذ وطالســم‬\n‫ســحرية و صــورة واحــدة تتضمــن إيحــاءات جنســية يف جهــاز هاتفهــا‬\n‫اجلــوال‪-2 .‬ثبــوت إدانــة املدعــى عليهــا بتصويــر ورقــة مــن ملــف إحــدى‬\n‫املريضــات دون مبــرر مقبــول ومعاقبتهــا علــى ذلــك بأخــذ التعهــد عليهــا‬\n‫بعــدم العــودة ملــا بــدر منهــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــي‬\n‫العــام عــدم قناعتــه ورغبتــه رفــع احلكــم حملكمــة االســتئناف بــدون‬\n‫الئحــة اعتراضيــة وقــررت املدعــى عليهــا عــدم قناعتهــا ورغبتهــا تقــدمي‬\n‫الئحــة اعتراضيــة فجــرى إفهامهــا بتعليمــات االســتئناف ففهمتهــا كمــا‬\n‫أفهمتهــا بــأال تنصــرف حتــى تتســلم نســخة مــن احلكــم وبــاهلل التوفيــق‬\n                    ‫وقد مت االنتهاء من حتريره يف متام الساعة ‪،،، 9 : 25‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1434/6/28‬ه ـ فتحت اجللســة‬\n‫الســاعة ‪ 8 : 00‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪ 34241045‬يف‬\n‫‪1434/6/14‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وقــد‬\n                            ‫مت االنتهــاء مــن حتريــره يف متــام الســاعة‪8 : 10‬‬\n\n\n\n\n                                                                                   ‫‪138‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":116,"source_page_end":138,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dc35a187e7a024929bdef9dc0a74de8627141225814e8cc9bf2e0a7ff462a1de","normalized_text_hash":"886f6117bc30b7c0ace878e74228107ce1abd0146fd5c9bdce2067b511036514","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p116-34206789"},{"id":"ea60d08b-ab90-523a-9030-97d73905b068","document_type":"judgment","category":"judicial","subcategory":"general","title":"ابتزاز -ابتزاز فتاة بنشر صورها -استغالل العمل إلقامة عالقة محرمة -جرائم معلوماتية -إقدام على الفاحشة مبقابل مادي - حيازة صور ومقاطع إباحية -حيازة حرز وطالسم سحرية -إقرار املدعى عليه بالفعل املؤثم -التعزير بالسجن واجللد والغرامة .","document_number":"34226363","case_number":"34219003","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وتضمن القرار طلب زيادة التعزير بحق املدعى عليه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/28","year":"1434","subject":"ابتزاز -ابتزاز فتاة بنشر صورها -استغالل العمل إلقامة عالقة محرمة -جرائم معلوماتية -إقدام على الفاحشة مبقابل مادي - حيازة صور ومقاطع إباحية -حيازة حرز وطالسم سحرية -إقرار املدعى عليه بالفعل املؤثم -التعزير بالسجن واجللد والغرامة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34226363 :‬تاريخه‪1434/05/28 :‬هـ‬\n                           ‫رقم الدعوى‪34219003:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34304090‬تاريخه‪1434/8/23 :‬هـ‬\n\n\n       ‫ابتــزاز ‪ -‬ابتــزاز فتــاة بنشــر صورهــا ‪ -‬اســتغالل العمــل إلقامــة عالقــة‬\n       ‫محرمــة ‪ -‬جرائــم معلوماتيــة ‪ -‬إقــدام علــى الفاحشــة مبقابــل مــادي ‪-‬‬\n       ‫حيــازة صــور ومقاطــع إباحيــة ‪ -‬حيــازة حــرز وطالســم ســحرية ‪ -‬إقــرار‬\n        ‫املدعــى عليــه بالفعــل املؤثــم ‪ -‬التعزيــر بالســجن واجللــد والغرامــة ‪.‬‬\n\n\n\n\n       ‫‪ -‬قولــه صلــى اهلل عليــه وســلم (ماتركــت بعــدي فتنــه أضــر علــى‬\n                                                    ‫الرجــال مــن النســاء )‪.‬‬\n                        ‫‪ -‬املادة (‪ )1/6‬من نظام مكافحة اجلرائم املعلوماتية ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه بابتــزاز إحــدى الفتيــات بنشــر‬\n       ‫صورهــا ‪ -‬وتكويــن عالقــة محرمــة مــع مجموعــة مــن الفتيــات ‪-‬‬\n       ‫وحيــازة مقطــع وصــور إباحيــة ‪ -‬وحيــازة طالســم ســحرية بهــا اســتعانة‬\n       ‫باجلــن ‪ ،‬حيــث تقدمــت املدعيــة لهيئــة األمــر باملعــروف والنهــي عــن‬\n       ‫املنكــر بشــكوى ضــد املدعــى عليــه مفادهــا قيامــه بابتزازهــا‬\n       ‫وتهديدهــا ومســاومتها علــى عرضهــا ‪ -‬وطلــب منهــا اخلــروج معــه ليختلــي‬\n       ‫بهــا ‪ -‬حيــث تعرفــت عليــه مســبق ًا عــن طريــق عملــه يف أحــد مكاتــب‬\n       ‫الســفريات ‪ -‬لكونــه يقــوم بأخــذ معلومــات عــن املســافرين ‪ -‬وبعــد‬\n\n‫‪139‬‬\n\f‫فتــرة اتصــل باملدعيــة ‪ -‬وأبــدى رغبتــه مــن الــزواج بهــا ‪ -‬وبعــد أن غــرر‬\n‫بهــا ‪ -‬بــدأ يف مســاومتها باخلــروج معــه ‪ -‬وإال ســيقوم بفضحهــا ‪ -‬فقامــت‬\n‫املــرأة مبواعدتــه ‪ -‬فتــم القبــض عليــه ‪ -‬وباإلطــاع علــى جــوال املدعــى‬\n‫عليــه ‪ -‬وجــدت رســائل كثيــرة صــادرة مــن جوالــه إلــى جــوال الفتــاة‬\n‫‪ -‬ورســائل أخــرى إلــى فتيــات أخريــات ‪ -‬كمــا ضبــط بجوالــه علــى‬\n‫صــور للفتــاة املشــتكية ‪ -‬ومجموعــة كبيــرة مــن الصــور اإلباحيــة‬\n‫والعاريــة ‪ -‬ومقاطــع فيديــو فاضحــة ‪ -‬ومجموعــة كبيــرة مــن صــور‬\n‫اجلــوازات ‪ -‬ومجموعــة كبيــرة مــن األســماء النســائية ‪ ،‬طلــب املدعــي‬\n‫العــام تعزيــر املدعــى عليــه بالســجن والغرامــة ومصــادرة هواتفــه اجلوالــة‬\n‫بإســقاط شــرائح اجلــواالت ‪ -‬وتعزيــره لقــاء تكوينــه عالقــة محرمــة مــع‬\n‫الفتيــات ‪ -‬وحيــازة الصــور واملقاطــع اإلباحيــة ‪ ،‬أقــر املدعــى عليــه مبــا‬\n‫جــاء بدعــوى املدعــي العــام ‪ -‬ودفــع أن احلــرز والطالســم التــي كانــت‬\n‫ا ‪-‬حكمــت‬       ‫معــه كانــت بهــدف الضــر والعــن واســتخدامه لهــا جه ـ ً‬\n‫احملكمــة بتعزيــر املدعــى عليــه بالســجن والغرامــة ومصــادرة الهاتــف‬\n‫املســتخدم يف اجلرميــة لقــاء حيازتــه لصــور ومقاطــع إباحيــة ‪ ،‬وتعزيــره‬\n‫بالســجن واجللــد لقــاء عالقتــه احملرمــة مــع النســاء ‪ ،‬وتعزيــره بالســجن‬\n‫واجللــد لقــاء ابتــزازه وطلــب فعــل الفاحشــة مــع إحداهــن ‪ ،‬وتعزيــره‬\n‫بالســجن واجللــد لقــاء حيــازة الطالســم الســحرية واحلــرز ‪ ،‬قــرر املدعــى‬\n‫عليــه اعتراضــه علــى احلكــم بــدون الئحــة ‪ -‬واملدعــي العــام قــرر‬\n‫اعتراضــه مكتفي ـ ًا بالئحــة الدعــوى‪ ،‬عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف وتضمــن القــرار طلــب زيــادة التعزيــر بحــق املدعــى عليــه ‪،‬‬\n‫احلكــم بزيــادة التعزيــر بحــق املدعــى عليــه عمــا ســبق احلكــم عليــه ‪،‬‬\n‫قنــع املدعــي عليــه باحلكــم واملدعــى العــام قــرر اعتراضــه علــى احلكــم‬\n‫مكتفي ـ ًا بالئحــة الدعــوى ‪ ،‬صــدق احلكــم مــن محكمــة اإلســتئناف‪.‬‬\n                                                                                   ‫‪140‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم‬\n      ‫‪ 34219003‬وتاريــخ ‪ 1434/05/12‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1434/05/12‬ه ـ ففــي يــوم األحــد املوافــق‪1434/05/26‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 5‬وفيهــا قــدم املدعــي العــام الئحــة‬\n      ‫ا فيهــا‬‫دعــوى عامــه ضــد ســعودي اجلنســية بالســجل املدنــي رقــم قائ ـ ً‬\n      ‫حيــث أنــه بتاريــخ ‪1434/4/11‬ه ـ ورد لــدى مركــز هيئــة مجمــع ‪....‬‬\n      ‫شــكوى خطيــة مــن قبــل إحــدى النســاء مفادهــا قيــام املذكــور أعــاه‬\n      ‫بتهديدهــا وابتزازهــا ومســاومتها علــى عرضهــا ويريــد مقابلتهــا يف‬\n      ‫مجمــع ‪ .....‬ليخــرج ويختلــي بهــا والــذي تعــرف عليهــا مســبق ًا اســتغال ًال‬\n      ‫لطبيعــة عملــه يف مكتــب للســفريات باخلبــر حيــث أنــه يأخــذ معلومــات‬\n      ‫املســافرين كاملــة حلاجتهــم إلبدائهــا لــه إلنهــاء إجــراءات ســفرهم ‪،‬‬\n      ‫وبعــد أخــذ معلومــات الفتــاة كاملــة اتصــل عليهــا بعــد فتــرة وذكــر لهــا‬\n      ‫أنــه أخــذ رقمهــا بعــد الرجــوع لســجالتهم يف املكتــب وأنــه يرغــب يف‬\n      ‫الــزواج منهــا لذلــك يريــد أن يــرى صــور زوجتــه املســتقبلية وبعــد أن غــرر‬\n      ‫بهــا متكــن مــن ذلــك وبــدأ يف مســاومتها علــى اخلــروج معــه وإال ســيقوم‬\n      ‫بفضحهــا ‪ ،‬فتــم رصــد املتهــم مــن قبــل أعضــاء هيئــة األمــر باملعــروف‬\n      ‫والنهــي عــن املنكــر حســب املوعــد الــذي حــدده للفتــاة املبتــزة ‪ ،‬وعنــد‬\n      ‫حضــوره مت القبــض عليــه وباالطــاع علــى محضــر مشــاهدة رســائل‬\n      ‫االبتــزاز الصــادرة مــن جــوال املتهــم مــن نــوع ‪ ....‬للفتــاة املشــتكية لوحــظ‬\n\n‫‪141‬‬\n\f‫رســالة نصهــا (اقــل مــن خمــس دقايــق يــا وصــورك كاملــه بصفحتــك‬\n‫علــى النــت واليوتيــوب والفيــس بــوك بــاي وعليهــم اســمك الرباعــي‬\n‫بالكامــل) كمــا لوحــظ رســالة أخــرى نصهــا (طيــب انــا حذرتــك‬\n‫وانتــي براحتــك بعــد شــوي راح جتيــك الروابــط وفيهــا صــورك وكل‬\n‫شــي عنــك بالنــت مــا كان ودي اســوي كــذا لكنــك جبرتينــي بــاي)‬\n‫ورســالة بعدهــا (بتــردي علــي وإال انشــر ابــي رد نهائــي) ورســائل أخــرى‬\n‫مرفقــة بالقضيــة كمــا أنــه باالطــاع علــى نفــس احملضــر لوحــظ قيــام‬\n‫املتهــم بإقامــة عالقــات محرمــة مــع فتيــات أخريــات وطلبــه لبعضهــن‬\n‫ملمارســة الفاحشــة معــه مبقابــل مــادي وابتــزاز فتــاة أخــرى ‪ ،‬فلوحظــت‬\n‫رســالة صــادرة مــن جوالــه إلــى فتــاة رمــز الســمها (‪ )....‬نصهــا (ليــش‬\n‫حذفتينــي ؟ تبغــي أدق علــى زوجــك واســمعه محادثتنــا وأوريــه ســوالفنا )‬\n‫كمــا لوحظــت رســالة صــادرة مــن جوالــه لفتــاة رمــز الســمها (‪ )....‬نصهــا‬\n‫(هــا عمــري انــا ابيــك ســهره معــي وبعطيــك ‪ 2000‬ريــال انتظــر ردك يــا‬\n‫قلبــي) ولوحظــت رســالة صــادرة لفتــاة رمــز الســمها (‪ ).....‬وهــو يغــرر بهــا‬\n‫مســتخدم ًا نفــس أســلوبه مــع الفتــاة املشــتكية ونــص الرســالة (صبــاح‬\n‫الــورد اممــم ســؤال مــره محــرج بصراحــه بــس يعلــم اهلل أنــي شــفت‬\n‫فيــك مواصفــات شــريكة حياتــي ولــو أنــه بــدري أقولــك هالــكالم‬\n‫لكنــك ســألتي وأنــا الزم أجــاوب مــن جــد معجــب فيــك ونفســي اتعــرف‬\n‫عليــك أكثــر وادخــل بحياتــك اكثــر) وبعدهــا طلــب صورهــا إلــى أن‬\n‫حصــل علــى صورتــن منهــا كمــا يتضــح ذلــك مــن خــال الرســائل‬\n‫‪ ،‬وممــا يوضــح مترســه لإليقــاع بالفتيــات رســائله مــع فتــاة يســميها ‪،‬‬\n‫حيــث كانــت ردة فعــل الفتــاة بدايــة األمــر باالنزعــاج وأنهــا فتــاة لديهــا‬\n‫نضــج وإدراك لفهــم قصــد املتهــم ‪ ،‬ثــم بعــد ذلــك مبتابعــة محادثتهمــا‬\n\n\n                                                                                     ‫‪142‬‬\n\f      ‫لوحظــت رســائل غراميــة بينهمــا ممــا يبــن إيقاعــه بالفتــاة بعــد متنعهــا‬\n      ‫ـداء ‪ ،‬ورســائل أخــرى كثيــرة ‪ -‬مرفقــة ويتعــذر كتابتهــا لكثرتهــا‬            ‫ابتـ ً‬\n      ‫ـداء‬\n      ‫ال لطبيعــة عملــه ابتـ ً‬     ‫‪ -‬مبينــة لعالقاتــه احملرمــة مــع الفتيــات مســتغ ً‬\n      ‫يف تكويــن العالقــات كمــا يتضــح ذلــك مــن الرســائل املتبادلــة ‪ ،‬ومــن‬\n      ‫أســماء الفتيــات (‪ ....)................‬إلــخ ‪ ،‬تتجــاوز (‪ )80‬فتــاة تقريبـ ًا حتــادث‬\n      ‫معهــن مــا بــن رســائل متعلقــة بحجــوزات الســفر إلــى رســائل التغريــر‬\n      ‫بزبائنــه مــن الفتيــات باإلعجــاب والغــرام وطلــب الــزواج وممارســة‬\n      ‫الفاحشــة واالبتــزاز ‪ .‬كمــا أنــه باالطــاع علــى محضــر مشــاهدة جــوال‬\n      ‫املتهــم (‪ ).....‬لوحــظ مــا يلــي‪ -1:‬عــدد (‪ )15‬صــورة للفتــاة املشــتكية يف‬\n      ‫عــدة أوضــاع مخلــة ‪ ،‬وصــور لعضــو ذكــري يتضــح أنهــا تعــود لنفــس‬\n      ‫املتهــم يتراســل بهــا مــع الفتــاة املبتــزة ‪ -2‬مجموعــة كبيــرة مــن صــور‬\n      ‫اجلــوازات الرســمية ‪ -3‬مجموعــة كبيــرة مــن الصــور اإلباحيــة والعاريــة‬\n      ‫ملجموعــة مــن النســاء ‪ -4‬مجموعــة كبيــرة مــن مقاطــع الفيديــو وبهــا‬\n      ‫نســاء يرقصــن بلبــاس شــبه عــار ‪ -5‬مقاطــع فيديــو متتابعــة لشــخص‬\n      ‫يقــوم مبمارســة العــادة الســرية ويقــوم بتصويــر نفســه ويعتقــد أنهــا تعــود‬\n      ‫لنفــس املتهــم ‪ -6‬مجموعــة كبيــرة مــن األســماء النســائية فيتضــح قيــام‬\n      ‫املتهــم باســتخدام جوالــه الشــخصي يف التعامــل مــع الزبائــن وتصويــر‬\n      ‫ال لعملــه الــذي‬ ‫جوازاتهــم الرســمية ويبــدأ بربــط عالقاتــه احملرمــة مســتغ ً‬\n      ‫يعمــل بــه فيأخــذ معلوماتهــن الشــخصية واالتصــال بهــن بداعــي إكمــال‬\n      ‫إجــراءات الســفر ثــم تبــدأ العالقــة معهــن ‪ -‬كمــا فعــل مــع الفتــاة املبتــزة‬\n      ‫وباالطــاع علــى جــوال املتهــم مــن نــوع (‪ )......‬لوحــظ حيازتــه علــى صــور‬\n      ‫مخلــة ومجموعــة مــن األســماء النســائية وباســتجواب املتهــم‪ /‬اعتــرف‬\n      ‫بتهديــد الفتــاة املشــتكية بنشــر صورهــا ألنهــا لــم تــرد عليــه وأنــه تعــرف‬\n\n\n‫‪143‬‬\n\f‫عليهــا عنــد حضورهــا ملكتــب الســفريات الــذي يعمــل بــه لعمــل حجــز‬\n‫‪ ،‬واعتــرف بحيازتــه حلــرز بداعــي حمايتــه مــن العــن وقــد ورد تقريــر‬\n‫مركــز هيئــة غــرب اخلبــر رقــم (‪ ).....‬وتاريــخ ‪1434/4/28‬ه ـ املتضمــن‬\n‫فحــص احلــرز املضبــوط بحــوزة املتهــم وتبــن أنــه عبــارة عــن جلــد كتــب‬\n‫فيــه بعــض االحــراز والطالســم الســحرية واالســتغاثة باجلــن وفصلــت‬\n‫الطالســم إلــى طلســم جللــب الــرزق ‪ ،‬و إبطــال الســحر ‪ ،‬و إلتيــان احملبــة‬\n‫‪ ،‬و لعقــد اللســان ‪ ،‬و للحســد ‪ ،‬ولشــفاء املريــض ‪ ،‬و لتحصيــل العمــل‬\n‫‪ ،‬و لتقويــة الذاكــرة ‪ ،‬و لزيــادة احلفــظ ‪ ،‬و لقبــول العــزة ‪ ،‬ويتبــن مــن‬\n‫ذلــك اســتعانة باجلــن مــن دون اهلل يعتقــد بهــا جلــب النفــع ودفــع الضــر‬\n‫وحمايــة لــه مــن أي بــاء ومت إتالفهــا بالكامــل ملــا أشــير إليــه أقــرر‬\n‫توجيــه االتهــام لــ‪ /‬بابتــزازه إلحــدى الفتيــات بنشــر صورهــا ‪ ،‬وتكوينــه‬\n‫لعالقــات محرمــة مــع مجموعــة كبيــرة مــن الفتيــات عــن طريــق التغريــر‬\n‫ال بذلــك جهــة عملــه وطلبــه لبعضهــن ملمارســة الفاحشــة معــه‬   ‫بهــن مســتغ ً‬\n‫مبقابــل مــادي ‪ ،‬وحيازتــه ملجموعــة كبيــرة مــن الصــور ومقاطــع الفيديو‬\n‫اإلباحيــة ‪ ،‬وحيازتــه حلــرز وطالســم ســحرية بهــا اســتعانة باجلــن مــن دون‬\n‫اهلل جللــب النفــع ودفــع الضــر وحمايــة لــه مــن أي بــاء وذلــك لألدلــة‬\n                                                             ‫والقرائــن اآلتيــة ‪:‬‬\n                 ‫‪ -1‬ما جاء يف اعترافه حتقيق ًا لفه (‪ )12-11‬و (‪. )44-43‬‬\n                                   ‫‪ -2‬ما جاء يف محضر القبض لفه (‪.)3-2‬‬\n                            ‫‪ -3‬ما جاء يف محضر مشاهدة اجلوال لفه (‪.)37‬‬\n              ‫‪ -4‬ما جاء يف محضر مشاهدة رسائل اجلوال لفه (‪.)36-17‬‬\n               ‫‪ -5‬ما جاء يف تقرير مركز هيئة غرب اخلبر لفه (‪.)48-47‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n\n\n                                                                                     ‫‪144‬‬\n\f      ‫فعــل محــرم شــرع ًا ومجــرم نظامـ ًا ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب‬\n                                 ‫إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باألتــي ‪:‬‬\n      ‫‪ -1‬احلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره لقــاء قيامــه‬\n      ‫ال بذلــك طبيعــة عملــه‬     ‫بتكويــن العالقــات احملرمــة مــع الفتيــات مســتغ ً‬\n      ‫‪ ،‬وحيازتــه لصــور ومقاطــع إباحيــة ‪ ،‬وحيازتــه حلــرز وطالســم ســحرية ‪.‬‬\n      ‫‪ -2‬احلكــم عليــه مبــا ورد يف املــادة (‪ )3‬الفقــرة (‪ )4‬مــن نظــام مكافحــة‬\n      ‫جرائــم املعلوماتيــة لقــاء قيامــه بابتــزاز إحــدى الفتيــات ‪ -3 .‬مصــادرة‬\n      ‫أجهــزة اجلــواالت العائــدة للمتهــم األول من نــوع ‪ .....‬والذي مت طلب حجزه‬\n      ‫مــن الشــرطة ‪ .....‬مبوجــب خطابنــا رقــم (‪ )3836‬وتاريــخ ‪1434/4/20‬ه ـ‬\n      ‫‪ ،‬والثانــي مــن نــوع ‪ ....‬رقمــه املصنعــي (‪ )...‬وإســقاط شــرائح االتصــاالت‬\n      ‫رقــم (‪ )...‬ورقــم (‪ )...‬وفقـ ًا للمــادة رقــم (‪ )13‬مــن نظــام مكافحــة جرائــم‬\n      ‫املعلوماتيــة (علمـ ًا بــأن احلــق اخلــاص مــا زال قائماً)هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليــه عــن الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى كلــه‬\n      ‫صحيــح فأنــا أعمــل يف مكتــب للســفريات وأقــوم بعمــل حجــوزات‬\n      ‫للعمــاء ونتيجــة لذلــك فقــد تعرفــت علــى مجموعــة كبيــرة مــن النســاء‬\n      ‫كنــت أقــوم بعمــل حجــوزات لهــن وقــد أصبحــت أتواصــل معهــن عــن‬\n      ‫طريــق الواتــس أب وأتبــادل معهــن الرســائل الغراميــة وقــد حصلــت علــى‬\n      ‫صــور لبعضهــن وطلبــت مــن احداهــن أن أقابلهــا وقــد هددتهــا إن هــي‬\n      ‫رفضــت بــأن أقــوم بنشــر صورهــا يف االنترنــت مكتوب ـ ًا عليهــا اســمها‬\n      ‫الرباعــي ولــم أقــم مبقابلتهــا حيــث مت القبــض علــي عندمــا تقدمــت‬\n      ‫هــي بالشــكوى ضــدي كمــا أنــي ســبق أن عرضــت علــى احداهــن أن‬\n      ‫أفعــل بهــا الفاحشــة مبقابــل مــادي لكنهــا رفضــت وبعــد القبــض علــي‬\n      ‫وجــد رجــال هيئــة األمــر باملعــروف يف جهــاز جوالــي نــوع ‪ ....‬صــور ًا للفتــاة‬\n\n\n‫‪145‬‬\n\f‫املشــتكية وكذلــك صــور ومقاطــع فيديــو اباحيــة وكذلــك كان‬\n‫يوجــد يف جهــاز جوالــي اآلخــر نــوع ‪ .....‬صــور مخلــه ومجموعــة من اســماء‬\n‫النســاء الالتــي تعرفــت عليهــن كمــا كان يوجــد معي عنــد القبض علي‬\n‫حــرز عبــارة عــن جلــد مكتــوب فيــه طالســم ســحريه بهــا اســتعانه باجلــن‬\n‫وذلــك بهــدف دفــع الضــر والعــن وجلــب النفــع وقــد اشــتريته مــن شــخص‬\n‫يف القطيــف ووضعتــه معــي نتيجــة اجلهــل وأنــا نــادم وتائــب إلــى اهلل‬\n‫تعالــى علمـ ًا بأنــي غيــر محصــن هكــذا أجــاب وأقفلــت اجللســة الســاعة‬\n‫العاشــرة إال ربــع للتأمــل وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم الثالثــاء ‪1434/5/28‬ه ـ الســاعة‬\n‫ـاء علــى مــا‬\n            ‫التاســعة والثلــث افتتحــت اجللســة بحضــور املدعــى عليــه فبنـ ً‬\n‫تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بتخزينــه يف جهــاز‬\n‫جوالــه نــوع ‪ ....‬صــور ًا للفتــاة املشــتكية وكذلــك صــور ًا ومقاطــع اباحيــه‬\n‫وهــذا اجلهــاز إلكترونــي ويف هــذا مســاس بالقيــم الدينيــة واآلداب‬\n‫العامــة واحليــاة اخلاصــة وقــد ارتكــب املدعــى عليــه اجلرميــة املشــار لهــا‬\n‫بالفقــرة (‪ )1‬مــن املــادة السادســة مــن نظــام مكافحــة جرائــم املعلوماتيــة‬\n‫وملــا جــاء يف املــادة الثالثــة عشــرة مــن ذات النظــام كمــا أقــر املدعــى‬\n‫عليــه بتخزينــه صــور ًا مخلــه ومجموعــه مــن اســماء النســاء الالتــي تعــرف‬\n‫عليهــن يف جهــاز جوالــه نــوع ‪ .....‬وحيــث أقــر املدعــى عليــه بتعرفــه علــى‬\n‫مجموعــة كبيــرة مــن النســاء وتبادلــه معهــن الرســائل الغراميــة وال‬\n‫شــك أن هــذا مــن دواعــي الفتنــة وقــد نهــى الشــارع عــن كل مــا يفضــي‬\n‫للفتنــة وبــن خطرهــا فقــال عليــه الصــاة والســام((ما تركــت فتنــة‬\n‫بعــدي أضــر علــى الرجــال مــن النســاء))وقد أقــر املدعــى عليــه بأنــه‬\n‫عــرض علــى احــدى النســاء أن يفعــل بهــا الفاحشــة مبقابــل مــادي ويف‬\n\n\n                                                                                     ‫‪146‬‬\n\f      ‫هــذا محاولــة إليقــاع النســاء بالرذيلــة كمــا أقــر بابتــزازه احــدى النســاء‬\n      ‫بتهديدهــا بنشــر صورهــا يف االنترنــت مكتوبـ ًا عليهــا اســمها الرباعــي‬\n      ‫إن لــم تقابلــه وأقــر املدعــى عليــه بحيازتــه حــرز فيــه طالســم ســحرية بهــا‬\n      ‫اســتعانه باجلــن لدفــع الضــر والعــن وقــد دفــع املدعــى عليــه باجلهــل يف‬\n      ‫حرمــة هــذا الفعــل لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي قيــام املدعــى‬\n      ‫عليــه باملســاس بالقيــم الدينيــة واآلداب العامــة وحرمــة احليــاة اخلاصــة‬\n      ‫وذلــك بتخزينــه صــور احــدى النســاء وصــور ومقاطــع فيديــو اباحيــه يف‬\n      ‫جهــاز جوالــه نــوع ‪ .....‬وهــو جهــاز إلكترونــي وقــررت تعزيــر املدعى عليه‬\n      ‫لقــاء ذلــك بســجنه مــدة ســتة أشــهر وتغرميــه مبلــغ خمســة االف ريــال‬\n      ‫ومصــادرة جهــازي اجلــوال العائديــن لــه نــوع‪.....‬و‪ .......‬ثاني ـ ًا ثبــت لــدي‬\n      ‫ابتــزاز املدعــى عليــه إلحــدى النســاء وذلــك بتهديدهــا بنشــر صورهــا يف‬\n      ‫االنترنــت مكتوبـ ًا عليهــا اســمها الرباعــي إن لــم تقابلــه وقــررت تعزيــره‬\n      ‫لقــاء ذلــك بســجنه مــدة أحــد عشــر شــهر ًا وجلــده تســعني جلــده ثالثـ ًا ثبــت‬\n      ‫لــدي اقامــة املدعــى عليــه لعالقــات مــع نســاء اجنبيــات بتواصلــه معهــن‬\n      ‫عــن طريــق الواتــس أب وتبادلــه معهــن الرســائل الغراميــه وعرضــه علــى‬\n      ‫احداهــن فعــل الفاحشــة مبقابــل مــادي وقــررت تعزيــره لقــاء ذلك بســجنه‬\n      ‫مــدة أربعــة أشــهر وجلــده خمســن جلــده رابعـ ًا ثبــت لــدي حيــازة املدعــى‬\n      ‫عليــه حــرز فيــه طالســم ســحريه بهــا اســتعانه باجلــن بهــدف دفــع الضــر‬\n      ‫والعــن وجلــب النفــع وقــررت تعزيــر املدعــى عليــه لقــاء ذلــك بســجنه مــدة‬\n      ‫ثالثــة أشــهر وجلــده ســتني جلــده وبذلــك يكــون مجمــوع ســجن املدعــى‬\n      ‫عليــه هــو ســنتان اعتبــار ًا مــن تاريــخ إيقافــه ومجمــوع جلــده هــو مائتــان‬\n      ‫جلــده علــى أربــع دفعــات متســاوية بــن الدفعــة واألخــرى مــدة ال تقــل‬\n      ‫عــن عشــرة أيــام ومبــا تقــدم حكمــت وبعــرض احلكــم لــم يقنــع املدعــى‬\n\n\n‫‪147‬‬\n\f‫عليــه واســتعد بتقــدمي الئحــة اعتراضيــه فأفهــم مبراجعــة احملكمــة يــوم‬\n‫غــد األربعــاء ‪1434/5/29‬ه ـ الســتالم صــورة احلكــم وتقــدمي اعتراضــه‬\n‫خــال ثالثــن يومــا إن لــم يقدمــه ســقط حقــه يف االعتــراض كمــا أن‬\n‫املدعــي العــام لــم يقنــع مكتفي ـ ًا مبــا قــدم يف الئحــة الدعــوى وأقفلــت‬\n            ‫اجللســة الســاعة العاشــرة وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم األربعــاء ‪1434/5/29‬ه ـ‬\n‫الســاعة التاســعة إال عشــر دقائــق حضــر املدعــى عليــه ‪ ....‬وجرى تســليمه‬\n‫صــورة احلكــم وأفهــم باملــدة النظاميــة لالعتــراض وصلــى اهلل وســلم‬\n                                                            ‫علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم الســبت ‪1434/6/17‬ه ـ‬\n‫الســاعة التاســعة إال خمس دقائق افتتحت اجللســة بحضور املدعى عليه‬\n‫باســل وجــرى االطــاع علــى الالئحــة االعتراضيــة املقيــدة باحملكمــة‬\n‫برقــم يف ‪1434/6/17‬ه ـ املكونــة مــن ثــاث صفحــات ولــم أجــد فيهــا‬\n‫مــا يؤثــر علــى احلكــم وقــد قــرر املدعــى عليــه بقولــه إن هــذه هــي الئحتي‬\n‫االعتراضيــة هكــذا قــرر وصلــى اهلل وســلم علــى نبينا محمــد‪ .‬احلمد هلل‬\n‫وحــده وبعــد ثــم إنــه يف هــذا اليــوم األحــد ‪1434/7/30‬هـ الســاعة الثامنة‬\n‫افتتحــت اجللســة بحضــور املدعــى عليــه وقــد عادت املعاملــة من محكمة‬\n‫االســتئناف باملنطقــة الشــرقية وبرفقهــا قــرار الدائــرة اجلزائيــة األولــى‬\n‫رقــم يف ‪1434/7/16‬ه ـ املتضمــن أنــه بدراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ أن مــا حكــم بــه فضيلتــه‬\n‫علــى املدعــى عليــه قليــل ملــا اعتــرف بــه ولكونــه أخــل بواجبــات عملــه‬\n‫واســتغل عملــه يف معصيــة اهلل واإلســاءة لصاحــب العمــل عــاوة علــى مــا‬\n‫قــام بــه ملالحظــة مــا ذكــر واكمــال الــازم ومــن ثــم اعــادة املعاملــة أ‪.‬ه ـ‬\n\n\n                                                                                       ‫‪148‬‬\n\f      ‫وحيــث ان مــا ذكــره أصحــاب الفضيلــة وفقهــم اهلل تعالــى يف محلــه لــذا‬\n      ‫فقــد قــررت الزيــادة يف تعزيــر املدعــى عليــه لقــاء ابتــزازه احــدى النســاء‬\n      ‫واملشــار لــه يف احلكــم بالفقــرة ثانيـ ًا وذلــك بســجنه مــدة شــهران وجلــده‬\n      ‫خمســن جلــده كمــا قــررت الزيــادة يف تعزيــره لقــاء اقامتــه لعالقــات‬\n      ‫مــع نســاء أجنبيــات واملشــار لــه بالفقــرة ثالثـ ًا وذلــك بســجنه مــدة شــهران‬\n      ‫وبــه حكمــت وبذلــك يكــون مجمــوع ســجن املدعــى عليــه هــو ســنتان‬\n      ‫وأربعــة أشــهر اعتبــار ًا مــن تاريــخ إيقافــه ومجمــوع جلــده هــو مائتــان‬\n      ‫وخمســون جلــده علــى خمــس دفعــات متســاوية بــن الدفعــة واألخــرى‬\n      ‫مــدة ال تقــل عــن عشــرة أيــام وال زلــت علــى مــا أجريتــه وحكمــت بــه‬\n      ‫ممــا ســوى ذلــك وبعــرض احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي‬\n      ‫العــام مكتفي ـ ًا مبــا قــدم يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة‬\n      ‫الثامنــة والثلــث وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬احلمــد هلل وحــده‬\n      ‫وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة األولــى مبحكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم وتاريــخ ‪1434/8/8‬ه ـ املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪ 34/1989159‬وتاريــخ ‪1434/8/16‬ه ـ املرفــق‬\n      ‫بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ املســجل برقــم وتاريــخ‬\n      ‫‪1434/5/28‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام ضــد‪ /‬يف قضيــة ابتــزاز‬\n      ‫واقامــة عالقــة محرمــة وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه ضبطــه بنــاء‬\n      ‫علــى قرارنــا رقــم يف ‪1434/7/16‬ه ـ قررنــا املصادقــة علــى احلكــم‬\n      ‫بعــد االجــراء االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                           ‫وصحبــه وســلم حــرر يف ‪1434/8/22‬هــ‪.‬‬\n\n\n‫‪149‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":139,"source_page_end":149,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"167ba7900c3f06c967cb8295abb492bfa8e35a3831c6a589dc98e4c024fd5887","normalized_text_hash":"6719a80dd2069e0033fdd2ccdad23b6c0896b889fdd56a0eccbc2320fb50acfa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p139-34226363"}]$archive_payload$::jsonb AS data)
